def path_code(name):
    return name.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A")


def parse_manifest(data, algorithm):
    result = {}
    length = hashlib.new(algorithm).digest_size * 2
    for line in data.decode("utf-8").splitlines():
        match = re.fullmatch(r"([0-9a-fA-F]{" + str(length) + r"})[ \t]+(.+)", line)
        if not match:
            raise PreservationError("Invalid checksum manifest line")
        value, path = match.groups()
        # Only the three RFC8493 pathname escapes are decoded.
        path = re.sub(r"%(25|0[dD]|0[aA])",
                      lambda m: {"25": "%", "0d": "\r", "0a": "\n"}[m.group(1).lower()], path)
        safe_name(path)
        if path in result:
            raise PreservationError("Repeated manifest member: " + path)
        result[path] = value.lower()
    return result


def checksums(root, names, algorithm):
    lines = []
    for name in sorted(names):
        data = read_regular(root, name)
        lines.append(digest(data, algorithm) + "  " + path_code(name) + "\n")
    return "".join(lines).encode("utf-8")


def file_names(root):
    result = []
    for parent, directories, files in os.walk(root, followlinks=False):
        for item in directories + files:
            path = Path(parent) / item
            if path.is_symlink():
                raise PreservationError("Bag symlinks are not accepted")
        for item in files:
            name = (Path(parent) / item).relative_to(root).as_posix()
            safe_name(name)
            result.append(name)
    return sorted(result)


def transfer_identity(binding, revision, organization="", contact="", source_profile=None):
    sender = {"organization": text(organization, "organization"),
              "contact": text(contact, "contact")}
    if any(c in sender["organization"] + sender["contact"] for c in "\r\n"):
        raise PreservationError("Bag contact values must be single line")
    revision_sha = digest(canonical(revision))
    preimage = {"source": binding["manifestSha256"], "review": revision["reviewSha256"],
                "revisionRecordSha256": revision_sha, "sender": sender, "profile": PROFILE}
    if source_profile is not None:
        preimage["sourceProfile"] = source_profile
    return {"schema": BAG_SCHEMA, "profile": PROFILE,
            **({"sourceProfile": source_profile} if source_profile is not None else {}),
            "id": "research-" + digest(canonical(preimage))[:24],
            "collectionId": "research-source-" + binding["manifestSha256"][:24],
            "source": binding, "reviewRevision": revision["revision"],
            "reviewSha256": revision["reviewSha256"],
            "revisionRecordSha256": revision_sha, "sender": sender, "metadataLicense": LICENSE}


def bag_information(identity, revision, payload_bytes, payload_files):
    info = [
        ("External-Identifier", identity["id"]),
        ("Bag-Group-Identifier", identity["collectionId"]),
        ("External-Description", "Reviewed OpenAlex metadata and " +
         ("complete declared source-only example" if identity.get("sourceProfile") else
          "complete retained native research edition")),
        ("Bagging-Date", revision["createdAt"][:10]),
        ("Payload-Oxum", str(payload_bytes) + "." + str(payload_files)),
    ]
    if identity["sender"]["organization"]:
        info.insert(0, ("Source-Organization", identity["sender"]["organization"]))
    if identity["sender"]["contact"]:
        info.insert(1, ("Contact-Email", identity["sender"]["contact"]))
    return info


def build(workspace, output, expected_revision, *, zipped=False):
    output = Path(output).absolute()
    with project_lock(workspace):
        project, prepared = project_files(workspace)
        current, revision = current_review(workspace, prepared)
        if expected_revision != current["revision"]:
            raise PreservationError("STALE_REVISION: reload the saved review before building")
        rows = mapped_records(prepared, revision["review"])
        source_profile = project.get("sourceProfile")
        identity = transfer_identity(prepared["binding"], revision,
                                     project["organization"], project["contact"], source_profile)
        bag_id = identity["id"]
        if output.exists():
            prior = verify(output)
            if prior["identity"] != identity:
                raise PreservationError("Existing output belongs to another source or review")
            return {**prior, "path": str(output), "reused": True}
        output.parent.mkdir(parents=True, exist_ok=True)
        stage_parent = Path(tempfile.mkdtemp(prefix=".research-bag-", dir=output.parent))
        bag = stage_parent / bag_id
        bag.mkdir(mode=0o700)
        try:
            _, src = load_original(Path(workspace) / "source")
            wanted = {row["identifier"]: row for row in rows if row["include"]}
            written = set()
            try:
                for name, data in source_inventory(src, source_profile["nativeFiles"] if source_profile else None):
                    write_new(bag / DOC / "native-export" / name, data)
                    if re.fullmatch(r"pages/[0-9]{8}/response\.json", name):
                        response = parse_json(data)
                        for work in response["results"]:
                            identifier = work.get("id")
                            if identifier in wanted and identifier not in written:
                                row = wanted[identifier]
                                record = oai_module().canonical(work)
                                if digest(record) != row["source"]["recordSha256"]:
                                    raise PreservationError("Record differs from its original source hash")
                                write_new(bag / row["payloadPath"], record)
                                written.add(identifier)
            finally:
                src.close()
            if source_profile:
                write_new(bag / DOC / "source-example.zip", read_regular(workspace, "source-example.zip"))
            if written != set(wanted):
                raise PreservationError("Selected record missing from the original native pages")
            write_new(bag / "data/metadata/metadata.csv", metadata_csv(rows))
            write_new(bag / "data/metadata/review.html",
                      report_html(prepared["binding"], rows, current["revision"], current["reviewSha256"], source_profile))
            write_new(bag / DOC / "profile.json", canonical(identity))
            write_new(bag / DOC / "source-binding.json", canonical(prepared["binding"]))
            write_new(bag / DOC / "review.json", canonical(revision))
            write_new(bag / DOC / "mapping.json", canonical(
                {"schema": SCHEMA + ".mapping", "records": rows}))
            write_new(bag / DOC / "records-review.csv", human_csv(rows))
            reconciliation = {"schema": SCHEMA + ".reconciliation",
                "sourceRecords": len(rows), "sourceOccurrences": prepared["summary"]["sourceOccurrences"],
                "includedRecords": len(wanted), "excludedRecords": len(rows) - len(wanted),
                "sourcePages": len(prepared["binding"]["pages"]),
                "includedIdentifiers": sorted(wanted),
                "excludedIdentifiers": [row["identifier"] for row in rows if not row["include"]],
                "sourceFieldIssues": prepared["summary"]["fieldIssues"],
                "reviewRevision": current["revision"], "reviewSha256": current["reviewSha256"]}
            write_new(bag / DOC / "reconciliation.json", canonical(reconciliation))
            write_new(bag / "bagit.txt", BAGIT)
            payload = file_names(bag / "data")
            payload = ["data/" + name for name in payload]
            total = sum((bag / name).stat().st_size for name in payload)
            info = bag_information(identity, revision, total, len(payload))
            write_new(bag / "bag-info.txt", "".join(key + ": " + value + "\n" for key, value in info).encode("utf-8"))
            for algorithm in ("sha256", "sha512"):
                write_new(bag / f"manifest-{algorithm}.txt", checksums(bag, payload, algorithm))
            tags = ["bagit.txt", "bag-info.txt", "manifest-sha256.txt", "manifest-sha512.txt"]
            for algorithm in ("sha256", "sha512"):
                write_new(bag / f"tagmanifest-{algorithm}.txt", checksums(bag, tags, algorithm))
            receipt = verify(bag)
            sync_tree(bag)
            if zipped:
                archive = stage_parent / "transfer.zip"
                with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as z:
                    for name in file_names(bag):
                        info = zipfile.ZipInfo(bag_id + "/" + name, date_time=(1980, 1, 1, 0, 0, 0))
                        info.compress_type = zipfile.ZIP_DEFLATED
                        info.external_attr = (stat.S_IFREG | 0o600) << 16
                        with z.open(info, "w", force_zip64=True) as target, (bag / name).open("rb") as source:
                            shutil.copyfileobj(source, target, 1024 * 1024)
                with archive.open("rb") as handle:
                    os.fsync(handle.fileno())
                # Exclusive link prevents a concurrent output from being overwritten.
                os.link(archive, output)
            else:
                os.rename(bag, output)
            fsync_dir(output.parent)
            return {**receipt, "path": str(output), "zipped": zipped, "reused": False}
        finally:
            shutil.rmtree(stage_parent)


class BagReader:
    def __init__(self, path):
        self.path = Path(path).absolute()
        if self.path.is_symlink():
            raise PreservationError("Bag source must not be a symlink")
        self.zip = zipfile.ZipFile(path) if self.path.is_file() else None
        self.prefix = ""
        self.entries = {}
        if self.zip:
            raw = self.zip.infolist()
            names = [item.filename for item in raw]
            if len(names) != len(set(names)):
                raise PreservationError("ZIP contains duplicate members")
            for info in raw:
                if info.is_dir():
                    safe_name(info.filename.rstrip("/"))
                    continue
                safe_name(info.filename)
                if (info.external_attr >> 16) & 0o170000 not in {0, stat.S_IFREG}:
                    raise PreservationError("ZIP member is not a regular file")
            declarations = [name for name in names if name == "bagit.txt" or name.endswith("/bagit.txt")]
            if len(declarations) != 1:
                raise PreservationError("Select one complete bag archive")
            self.prefix = declarations[0][:-len("bagit.txt")]
            for info in raw:
                if info.is_dir():
                    continue
                if not info.filename.startswith(self.prefix):
                    raise PreservationError("ZIP contains data outside the selected bag")
                name = safe_name(info.filename[len(self.prefix):])
                self.entries[name] = info
            self.names = sorted(self.entries)
            sizes = [entry.file_size for entry in self.entries.values()]
        else:
            if not self.path.is_dir():
                raise PreservationError("Select an existing bag directory or ZIP")
            self.names = file_names(self.path)
            sizes = [(self.path / name).stat().st_size for name in self.names]
        if any(size > MAX_MEMBER for size in sizes) or sum(sizes) > MAX_TOTAL:
            raise PreservationError("Bag exceeds the configured member or total intake limit")

    def close(self):
        if self.zip:
            self.zip.close()

    def read(self, name):
        safe_name(name)
        if name not in self.names:
            raise PreservationError("Missing bag member: " + name)
        return self.zip.read(self.entries[name]) if self.zip else read_regular(self.path, name)

    def json(self, name):
        return parse_json(self.read(name))


def _verify_reader(reader):
    names = set(reader.names)
    if reader.read("bagit.txt") != BAGIT:
        raise PreservationError("Expected the BagIt 1.0 UTF-8 transfer profile")
    payload = {name for name in names if name.startswith("data/")}
    tags = names - payload - {"tagmanifest-sha256.txt", "tagmanifest-sha512.txt"}
    expected_tags = {"bagit.txt", "bag-info.txt", "manifest-sha256.txt", "manifest-sha512.txt"}
    if tags != expected_tags:
        raise PreservationError("Unexpected or missing transfer tag members")
    for algorithm in ("sha256", "sha512"):
        for prefix, expected in (("manifest", payload), ("tagmanifest", tags)):
            values = parse_manifest(reader.read(f"{prefix}-{algorithm}.txt"), algorithm)
            if set(values) != expected:
                raise PreservationError("Manifest inventory differs from actual members")
            for name, expected_sha in values.items():
                if digest(reader.read(name), algorithm) != expected_sha:
                    raise PreservationError("Checksum mismatch: " + name)
    info = {}
    for line in reader.read("bag-info.txt").decode("utf-8").splitlines():
        key, sep, value = line.partition(": ")
        if not sep or key in info or not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_.-]*", key):
            raise PreservationError("Invalid or duplicate bag information label")
        info[key] = value
    total = sum(len(reader.read(name)) for name in payload)
    if info.get("Payload-Oxum") != f"{total}.{len(payload)}":
        raise PreservationError("Payload-Oxum differs from the actual payload")
    identity = reader.json(DOC + "profile.json")
    if identity.get("schema") != BAG_SCHEMA or identity.get("profile") != PROFILE:
        raise PreservationError("Unsupported Archivematica research transfer profile")
    binding = reader.json(DOC + "source-binding.json")
    if identity.get("source") != binding or identity.get("metadataLicense") != LICENSE:
        raise PreservationError("Transfer source binding differs from its profile")
    revision = reader.json(DOC + "review.json")
    mapping = reader.json(DOC + "mapping.json")
    reconciliation = reader.json(DOC + "reconciliation.json")
    if (mapping.get("schema") != SCHEMA + ".mapping"
            or reconciliation.get("schema") != SCHEMA + ".reconciliation"
            or revision.get("schema") != SCHEMA + ".revision"):
        raise PreservationError("Unsupported saved transfer documentation")
    if (type(revision.get("revision")) is not int or revision["revision"] < 0
            or revision.get("reviewSha256") != digest(canonical(revision.get("review")))):
        raise PreservationError("Saved review digest changed")
    if (identity.get("reviewSha256") != revision["reviewSha256"]
            or identity.get("reviewRevision") != revision.get("revision")):
        raise PreservationError("Review and transfer revision identity differ")
    # Reuse the original source checker directly on either archive or directory.
    native_path = DOC + "native-export"
    source_path = reader.path
    source_prefix = (reader.prefix + native_path).strip("/")
    prepared = oai_module().prepare(source_path, source_prefix)
    if prepared["binding"] != binding:
        raise PreservationError("Original native query/page binding differs from the transfer")
    review = normalize_review(revision["review"], prepared)
    rows = mapped_records(prepared, review)
    if mapping["records"] != rows:
        raise PreservationError("Descriptive mapping differs from source plus saved review")
    sender = identity.get("sender")
    if not isinstance(sender, dict) or set(sender) != {"organization", "contact"}:
        raise PreservationError("Missing frozen bag sender inputs")
    source_profile = None
    if identity.get("sourceProfile") is not None:
        source_profile = retained_source_profile(
            identity, reader.read(DOC + "source-example.zip"),
            reader.read(DOC + "native-export/manifest.json"))
    expected_identity = transfer_identity(binding, revision, sender["organization"], sender["contact"], source_profile)
    if identity != expected_identity:
        raise PreservationError("Transfer identity differs from its immutable revision and sender inputs")
    if info != dict(bag_information(identity, revision, total, len(payload))):
        raise PreservationError("Bag information differs from the frozen transfer identity")
    if reader.read("data/metadata/review.html") != report_html(binding, rows, revision["revision"], revision["reviewSha256"], source_profile):
        raise PreservationError("Human receiving report differs from its source and review")
    if reader.read(DOC + "records-review.csv") != human_csv(rows):
        raise PreservationError("Spreadsheet review differs from its source and review")
    if reader.read("data/metadata/metadata.csv") != metadata_csv(rows):
        raise PreservationError("Archivematica descriptive CSV differs from the reviewed mapping")
    record_paths = {row["payloadPath"] for row in rows if row["include"]}
    if {name for name in payload if name.startswith("data/records/")} != record_paths:
        raise PreservationError("Selected JSON payload inventory differs from the saved review")
    for row in rows:
        if row["include"] and digest(reader.read(row["payloadPath"])) != row["source"]["recordSha256"]:
            raise PreservationError("Selected original record checksum changed")
    included = [row["identifier"] for row in rows if row["include"]]
    excluded = [row["identifier"] for row in rows if not row["include"]]
    if (reconciliation.get("includedIdentifiers") != sorted(included)
            or reconciliation.get("excludedIdentifiers") != excluded
            or reconciliation.get("sourceRecords") != len(rows)
            or reconciliation.get("includedRecords") != len(included)
            or reconciliation.get("excludedRecords") != len(excluded)
            or reconciliation.get("sourceOccurrences") != prepared["summary"]["sourceOccurrences"]
            or reconciliation.get("sourcePages") != len(binding["pages"])
            or reconciliation.get("sourceFieldIssues") != prepared["summary"]["fieldIssues"]
            or reconciliation.get("reviewRevision") != revision["revision"]
            or reconciliation.get("reviewSha256") != revision["reviewSha256"]):
        raise PreservationError("Transfer reconciliation differs from its actual selected records")
    src = oai_module().ExportSource(source_path, source_prefix)
    try:
        native_files = source_profile["nativeFiles"] if source_profile else src.manifest["files"]
        native_members = {DOC + "native-export/" + name for name in native_files}
        native_members.add(DOC + "native-export/manifest.json")
        if {name for name in payload if name.startswith(DOC + "native-export/")} != native_members:
            raise PreservationError("Original native source member inventory changed")
        expected_documentation = {DOC + name for name in (
            "profile.json", "source-binding.json", "review.json", "mapping.json",
            "records-review.csv", "reconciliation.json")}
        expected_payload = record_paths | native_members | expected_documentation | {
            "data/metadata/metadata.csv", "data/metadata/review.html"}
        if source_profile:
            expected_payload.add(DOC + "source-example.zip")
        if payload != expected_payload:
            raise PreservationError("Payload has members outside this transfer profile")
        for name in native_files:
            safe_name(name)
            src.read(name)
    finally:
        src.close()
    return {"schema": SCHEMA + ".verification", "valid": True,
            "identity": identity, "bagId": identity["id"], "metadataProfile": PROFILE,
            "members": len(names), "payloadFiles": len(payload), "payloadBytes": total,
            "sourceRecords": len(rows), "includedRecords": len(included), "excludedRecords": len(excluded),
            "sourcePages": len(binding["pages"]),
            "manifestSha256": digest(reader.read("manifest-sha256.txt")),
            "payloadOxum": info["Payload-Oxum"]}


def verify(path):
    reader = BagReader(path)
    try:
        return _verify_reader(reader)
    finally:
        reader.close()


def receive(source, output):
    output = Path(output).absolute()
    reader = BagReader(source)
    stage = None
    try:
        receipt = _verify_reader(reader)
        if output.exists():
            existing = verify(output)
            if existing["manifestSha256"] != receipt["manifestSha256"] or existing["identity"] != receipt["identity"]:
                raise PreservationError("Existing receiving directory contains a different transfer")
            return {**existing, "path": str(output), "reused": True}
        output.parent.mkdir(parents=True, exist_ok=True)
        stage = Path(tempfile.mkdtemp(prefix=".research-receive-", dir=output.parent))
        for name in reader.names:
            write_new(stage / name, reader.read(name))
        received = verify(stage)
        if received != receipt:
            raise PreservationError("Received bag differs from the verified source")
        sync_tree(stage)
        os.rename(stage, output)
        stage = None
        fsync_dir(output.parent)
        return {**received, "path": str(output), "reused": False}
    finally:
        reader.close()
        if stage:
            shutil.rmtree(stage)


def compare(previous, current):
    readers = [BagReader(previous), BagReader(current)]
    try:
        receipts = [_verify_reader(reader) for reader in readers]
        rows = [{row["identifier"]: row for row in reader.json(DOC + "mapping.json")["records"]}
                for reader in readers]
        old, new = rows
        identifiers = sorted(set(old) | set(new))
        changes = []
        for identifier in identifiers:
            before, after = old.get(identifier), new.get(identifier)
            status = []
            if before is None:
                status.append("SOURCE_ADDED")
            elif after is None:
                status.append("SOURCE_ABSENT")
            else:
                if before["source"]["recordSha256"] != after["source"]["recordSha256"]:
                    status.append("SOURCE_RECORD_CHANGED")
                if before["include"] != after["include"]:
                    status.append("INCLUDED" if after["include"] else "EXCLUDED")
                if before["reviewedDc"] != after["reviewedDc"]:
                    status.append("DESCRIPTIVE_METADATA_CHANGED")
                if before.get("decision") != after.get("decision"):
                    status.append("REVIEW_CHANGED")
            if status:
                changes.append({"identifier": identifier, "changes": status,
                                "before": before, "after": after})
        return {"schema": SCHEMA + ".comparison",
                "previous": receipts[0]["identity"], "current": receipts[1]["identity"],
                "summary": {"previousRecords": len(old), "currentRecords": len(new), "changedRecords": len(changes),
                    "sourceAdded": sum("SOURCE_ADDED" in row["changes"] for row in changes),
                    "sourceAbsent": sum("SOURCE_ABSENT" in row["changes"] for row in changes),
                    "sourceChanged": sum("SOURCE_RECORD_CHANGED" in row["changes"] for row in changes),
                    "metadataChanged": sum("DESCRIPTIVE_METADATA_CHANGED" in row["changes"] for row in changes)},
                "changes": changes,
                "receivingNote": "Source absence and review exclusion identify transfer differences. The receiving institution chooses its preservation and retention action."}
    finally:
        for reader in readers:
            reader.close()


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    p = sub.add_parser("init", help="Freeze an original completed research export")
    p.add_argument("--source", required=True); p.add_argument("--prefix", default="")
    p.add_argument("--workspace", required=True); p.add_argument("--organization", default="")
    p.add_argument("--contact", default="")
    for name in ("show", "review-template"):
        p = sub.add_parser(name); p.add_argument("--workspace", required=True)
    p = sub.add_parser("review-save", help="Save corrections and exclusions at the expected revision")
    p.add_argument("--workspace", required=True); p.add_argument("--input", required=True)
    p.add_argument("--expected-revision", type=int, required=True)
    p = sub.add_parser("build", help="Create a complete reviewed BagIt transfer")
    p.add_argument("--workspace", required=True); p.add_argument("--output", required=True)
    p.add_argument("--expected-revision", type=int, required=True); p.add_argument("--zip", action="store_true")
    p = sub.add_parser("verify"); p.add_argument("--source", required=True)
    p = sub.add_parser("receive"); p.add_argument("--source", required=True); p.add_argument("--output", required=True)
    p = sub.add_parser("compare"); p.add_argument("--previous", required=True); p.add_argument("--current", required=True)
    args = parser.parse_args(argv)
    try:
        if args.command == "init":
            result = initialize(args.source, args.workspace, args.prefix,
                                organization=args.organization, contact=args.contact)
        elif args.command in {"show", "review-template"}:
            result = show(args.workspace)
            if args.command == "review-template":
                result = result["review"]
        elif args.command == "review-save":
            result = save_review(args.workspace, parse_json(Path(args.input).read_bytes()), args.expected_revision)
        elif args.command == "build":
            result = build(args.workspace, args.output, args.expected_revision, zipped=args.zip)
        elif args.command == "verify":
            result = verify(args.source)
        elif args.command == "receive":
            result = receive(args.source, args.output)
        else:
            result = compare(args.previous, args.current)
        print(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False))
        return 0
    except (PreservationError, ValueError, KeyError, OSError, zipfile.BadZipFile) as exc:
        print(json.dumps({"error": type(exc).__name__, "message": str(exc)}, ensure_ascii=False), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Retained Preservica OPEX upload and complete source-linked repository receiving.

Uses the documented Preservica access-token header and S3-compatible upload API.
No tenant is created, no credentials are stored, and uncertain uploads are not
silently replaced. See PRESERVICA_PROVIDER_CONTRACT.md for source/version scope.
"""
from __future__ import annotations

import argparse
import base64
import contextlib
import datetime as dt
import email.utils
import fcntl
import hashlib
import html
import http.client
import json
import os
from pathlib import Path
import re
import socket
import ssl
import stat
import sys
import tempfile
import urllib.parse as url
import uuid
import xml.etree.ElementTree as ET
from collections import Counter

sys.path.insert(0, str(Path(__file__).resolve().parent))
import preservation as p
import preservica as q

SCHEMA = "stellar-forge.preservica-operation.v1"
CONFIGURATION_SCHEMA = "stellar-forge.preservica-configuration.v1"
EVIDENCE_SCHEMA = "stellar-forge.preservica-original-upload-evidence.v1"
S3_NS = "http://s3.amazonaws.com/doc/2006-03-01/"
STATUS_NS = "http://status.preservica.com"
CHUNK = 256 * 1024
MAX_STATE = 16 * 1024 * 1024
API_SOURCE = {
    "upload": "https://developers.preservica.com/api-reference/3-upload-content-s3-compatible",
    "opex": "https://developers.preservica.com/documentation/open-preservation-exchange-opex",
    "progress": "https://developers.preservica.com/api-reference/4-progress-token-api",
    "monitor": "https://developers.preservica.com/api-reference/5-process-monitoring-api",
    "entityImplementation": "https://github.com/carj/pyPreservica/blob/5a53e7e219ac16d28a5c77640518a596c0e8c088/pyPreservica/entityAPI.py",
    "monitorImplementation": "https://github.com/carj/pyPreservica/blob/5a53e7e219ac16d28a5c77640518a596c0e8c088/pyPreservica/monitorAPI.py",
}
PROGRESS = {"ABORTED", "ACTIVE", "COMPLETED", "PENDING", "SUSPENDING",
            "SUSPENDED", "UNKNOWN", "FAILED", "FINISHED_MIXED_OUTCOME", "CANCELLED"}
ACTIVE = {"ACTIVE", "PENDING", "SUSPENDING", "SUSPENDED", "UNKNOWN"}
FAILED = {"ABORTED", "FAILED", "FINISHED_MIXED_OUTCOME", "CANCELLED"}
PATHS = {"SO": "structural-objects", "IO": "information-objects", "CO": "content-objects"}
SAFE_QUERY = {"start", "max", "type", "value", "monitor", "status", "category",
              "uploadId", "partNumber", "uploads"}
SECRET_HEADERS = {"authorization", "proxy-authorization", "cookie", "set-cookie",
                  "preservica-access-token", "x-amz-security-token"}
URL_PATTERN = re.compile(r"https?://[^\s<>\"']+")


class Error(ValueError):
    pass


class Stop(Exception):
    def __init__(self, state, code, *, retry_at=None):
        super().__init__(code)
        self.state, self.code, self.retry_at = state, code, retry_at


class Unresolved(Exception):
    def __init__(self, code, *, details=None):
        super().__init__(code)
        self.code, self.details = code, details or {}


def clone(value):
    return p.parse_json(p.canonical(value))


def digest(value):
    return p.digest(p.canonical(value))


def require(condition, message):
    if not condition:
        raise Error(message)


def version(value):
    require(isinstance(value, str) and re.fullmatch(r"[0-9]+\.[0-9]+(?:\.[0-9]+)?", value),
            "Select an explicit Preservica major.minor version")
    result = ".".join(str(int(x)) for x in value.split(".")[:2])
    require(tuple(map(int, result.split("."))) >= (6, 2), "The OPEX ZIP profile requires version 6.2 or later")
    return result


def reference(value, label="reference", *, nullable=False):
    if value is None and nullable:
        return None
    try:
        require(isinstance(value, str), "Enter a UUID " + label)
        result = str(uuid.UUID(value))
    except (ValueError, TypeError, AttributeError):
        raise Error("Enter a UUID " + label)
    return result


def operation_id(value):
    require(isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,119}", value)
            and value not in {".", ".."}, "Use a stable operation ID of at most 120 safe characters")
    return value


def configuration_template():
    return {"schema": CONFIGURATION_SCHEMA, "origin": "https://YOUR-TENANT.preservica.com",
            "tenant": "YOUR_TENANT", "targetVersion": "9.3",
            "accessTokenEnv": "PRESERVICA_ACCESS_TOKEN", "parentRef": None,
            "uploadMode": "auto", "partBytes": 8 * 1024 * 1024,
            "requestTimeoutSeconds": 60, "maxResponseBytes": 8 * 1024 * 1024,
            "readbackBatchSize": 25}


def validate_configuration(configuration):
    require(isinstance(configuration, dict), "Configuration must be an object")
    template = configuration_template()
    require(not (set(configuration) - set(template)), "Unknown Preservica configuration field")
    required = {"origin", "tenant", "targetVersion", "accessTokenEnv", "parentRef"}
    require(required.issubset(configuration), "Select origin, tenant, version, token environment name and parentRef")
    result = {**template, **configuration}
    require(result["schema"] == CONFIGURATION_SCHEMA, "Unsupported configuration schema")
    raw = result["origin"]
    require(isinstance(raw, str) and len(raw) <= 2048 and not any(ord(c) < 33 for c in raw),
            "Select one HTTPS API origin")
    parsed = url.urlsplit(raw)
    try:
        port = parsed.port
    except ValueError:
        raise Error("Invalid API origin port")
    loopback = parsed.hostname in {"127.0.0.1", "::1", "localhost"}
    require(parsed.scheme == "https" or (parsed.scheme == "http" and loopback),
            "HTTPS is required except for an explicit local receiving service")
    require(parsed.hostname and not parsed.username and not parsed.password
            and parsed.path in {"", "/"} and not parsed.query and not parsed.fragment,
            "Origin cannot contain credentials, a path, query or fragment")
    host = parsed.hostname.lower()
    require(not host.endswith(".") and re.fullmatch(r"[A-Za-z0-9.:-]+", host), "Invalid API origin hostname")
    if ":" in host:
        host = "[" + host + "]"
    result["origin"] = parsed.scheme + "://" + host + (":" + str(port) if port else "")
    require(isinstance(result["tenant"], str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_-]{0,119}", result["tenant"]),
            "Enter the existing tenant identifier")
    require(result["tenant"] != "YOUR_TENANT" and "YOUR-TENANT" not in raw.upper(),
            "Replace the configuration template with the selected existing tenant")
    result["targetVersion"] = version(result["targetVersion"])
    name = result["accessTokenEnv"]
    require(isinstance(name, str) and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]{0,127}", name),
            "Use an environment variable name; never paste an access token")
    result["parentRef"] = reference(result["parentRef"], "parentRef", nullable=True)
    require(result["uploadMode"] in {"auto", "single", "multipart"}, "Unknown upload mode")
    bounds = {"partBytes": (5 * 1024 * 1024, 128 * 1024 * 1024),
              "requestTimeoutSeconds": (1, 300), "maxResponseBytes": (65536, 64 * 1024 * 1024),
              "readbackBatchSize": (1, 250)}
    for key, (low, high) in bounds.items():
        value = result[key]
        require(isinstance(value, int) and not isinstance(value, bool) and low <= value <= high,
                key + " is outside the supported range")
    return clone(result)


def _cancelled(cancelled):
    if cancelled is None:
        return
    stopped = cancelled() if callable(cancelled) else (
        cancelled.is_set() if hasattr(cancelled, "is_set") else bool(cancelled))
    if stopped:
        raise Stop("INTERRUPTED", "CANCELLED_BETWEEN_REQUESTS")


def _stamp(value):
    return (value.st_dev, value.st_ino, value.st_size, value.st_mtime_ns, value.st_ctime_ns)


def _xml(raw):
    require(isinstance(raw, bytes), "Expected retained XML bytes")
    require(b"<!DOCTYPE" not in raw.upper() and b"<!ENTITY" not in raw.upper(),
            "DTD/entity declarations are not accepted")
    try:
        return ET.fromstring(raw)
    except ET.ParseError:
        raise Unresolved("INVALID_XML_RESPONSE")


def _local(element):
    return element.tag.rsplit("}", 1)[-1] if isinstance(element.tag, str) else ""


def _text(element, name, namespace=None):
    if namespace:
        candidates = element.findall(".//{" + namespace + "}" + name)
        if element.tag == "{" + namespace + "}" + name:
            candidates = [element] + candidates
    else:
        candidates = [x for x in element.iter() if _local(x) == name]
    values = ["".join(x.itertext()) for x in candidates]
    if len(values) > 1 and len(set(values)) != 1:
        raise Unresolved("AMBIGUOUS_RESPONSE_FIELD", details={"field": name})
    return values[0] if values else None


def _retry_at(value):
    now = dt.datetime.now(dt.timezone.utc)
    try:
        if re.fullmatch(r"[0-9]+", value or ""):
            return (now + dt.timedelta(seconds=min(int(value), 86400 * 30))).isoformat().replace("+00:00", "Z")
        parsed = email.utils.parsedate_to_datetime(value)
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=dt.timezone.utc)
        return max(now, parsed.astimezone(dt.timezone.utc)).isoformat().replace("+00:00", "Z")
    except (ValueError, TypeError, OverflowError):
        return (now + dt.timedelta(seconds=60)).isoformat().replace("+00:00", "Z")


def _future(value):
    if not value:
        return False
    try:
        return dt.datetime.fromisoformat(value.replace("Z", "+00:00")) > dt.datetime.now(dt.timezone.utc)
    except (ValueError, TypeError):
        raise Error("Invalid retained retry timestamp")


def _safe_url(value, origin):
    try:
        parsed = url.urlsplit(html.unescape(value))
        if parsed.scheme not in {"http", "https"}:
            return value
        host = parsed.hostname or ""
        if ":" in host:
            host = "[" + host + "]"
        authority = host + (":" + str(parsed.port) if parsed.port else "")
        actual_origin = parsed.scheme + "://" + authority
        if actual_origin == origin:
            pairs = url.parse_qsl(parsed.query, keep_blank_values=True)
            query = url.urlencode([(k, v if k in SAFE_QUERY else "[REDACTED]") for k, v in pairs])
        else:
            query = "REDACTED_QUERY" if parsed.query else ""
        return url.urlunsplit((parsed.scheme, authority, parsed.path, query, ""))
    except (ValueError, TypeError):
        return "[UNUSABLE_PROVIDER_URL]"


def _safe_text(value, origin, token=None):
    if token:
        value = value.replace(token, "[REDACTED_ACCESS_TOKEN]")
    def replace_url(match):
        original = match.group(0)
        changed = _safe_url(original, origin)
        return changed.replace("&", "&amp;") if "&amp;" in original else changed
    return URL_PATTERN.sub(replace_url, value)


def _safe_value(value, origin, token=None):
    if isinstance(value, str):
        return _safe_text(value, origin, token)
    if isinstance(value, list):
        return [_safe_value(item, origin, token) for item in value]
    if isinstance(value, dict):
        return {key: _safe_value(item, origin, token) for key, item in value.items()}
    return value


def _safe_body(raw, origin, token=None):
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return raw, False
    replaced = _safe_text(text, origin, token)
    return (raw, False) if replaced == text else (replaced.encode("utf-8"), True)


def _safe_headers(headers, origin, token=None):
    result = {}
    for key, value in headers:
        name = key.lower()
        if name in SECRET_HEADERS:
            continue
        safe = _safe_text(value, origin, token)
        if name in result and result[name] != safe:
            result[name] = result[name] + ", " + safe
        else:
            result[name] = safe
    return result


def _atomic_json(path, value):
    p.replace_bytes(path, p.canonical(value))


def _new_json(path, value):
    data = p.canonical(value)
    if path.exists():
        require(p.read_regular(path.parent, path.name, MAX_STATE) == data, "Immutable journal entry changed")
    else:
        p.write_new(path, data)


@contextlib.contextmanager
def _operation_lock(directory):
    fd = os.open(directory / "operation.lock", os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        require(stat.S_ISREG(os.fstat(fd).st_mode), "Operation lock is not a regular file")
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise Error("This original operation is already active")
        yield
    finally:
        os.close(fd)


def _load(root, relative, limit=MAX_STATE):
    return p.parse_json(p.read_regular(root, relative, limit))


def _binding(root, handoff):
    return {"id": handoff["id"], "handoff": q.file_digest(root / "handoff.json"),
            "manifest": q.file_digest(root / "MANIFEST.json"),
            "transfer": clone(handoff["transfer"]), "source": clone(handoff["source"]),
            "packageSourceId": handoff["packageSourceId"],
            "recordsFolderSourceId": handoff["recordsFolderSourceId"],
            "includedRecords": handoff["counts"]["includedRecords"]}


def _read_state(directory, planned):
    pointer = _load(directory, "current.json")
    require(pointer.get("schema") == SCHEMA + ".current", "Unsupported operation state pointer")
    relative = pointer.get("path")
    require(isinstance(relative, str) and re.fullmatch(r"states/[0-9]{8}-[0-9a-f]{64}\.json", relative),
            "Invalid operation state path")
    raw = p.read_regular(directory, relative, MAX_STATE)
    require(p.digest(raw) == pointer.get("sha256") and len(raw) == pointer.get("bytes"),
            "Operation state bytes changed")
    state = p.parse_json(raw)
    require(state.get("schema") == SCHEMA + ".state" and state.get("planSha256") == digest(planned)
            and state.get("operationId") == planned["operationId"], "Operation state belongs to another plan")
    require(state.get("revision") == pointer.get("revision"), "Operation state revision changed")
    return state


def _save_state(root, directory, planned, state):
    with p.project_lock(root):
        prior = _read_state(directory, planned) if (directory / "current.json").exists() else None
        if prior:
            require(state["revision"] == prior["revision"], "Original operation state changed concurrently")
        else:
            require(state["revision"] == -1, "Initial operation state is not empty")
        state["previousStateSha256"] = digest(prior) if prior else None
        state["revision"] += 1
        state["updatedAt"] = p.utc()
        raw = p.canonical(state)
        require(len(raw) <= MAX_STATE, "Operation state exceeded its retained byte limit")
        relative = "states/" + format(state["revision"], "08d") + "-" + p.digest(raw) + ".json"
        p.write_new(directory / relative, raw)
        _atomic_json(directory / "current.json", {"schema": SCHEMA + ".current", "path": relative,
            "bytes": len(raw), "sha256": p.digest(raw), "revision": state["revision"]})


def plan(package_workspace, configuration, operation_id):
    config = validate_configuration(configuration)
    identifier = globals()["operation_id"](operation_id)
    root = Path(package_workspace).absolute()
    handoff = q.verify_workspace(root)
    selected = handoff["settings"].get("targetPreservicaVersion")
    if selected is not None:
        require(version(selected) == config["targetVersion"], "Package and client select different target versions")
    bound = _binding(root, handoff)
    object_key = "commons-" + identifier + "-" + bound["transfer"]["sha256"][:24] + ".zip"
    mode = config["uploadMode"]
    if mode == "auto":
        mode = "single" if bound["transfer"]["bytes"] <= config["partBytes"] else "multipart"
    stable = {"schema": SCHEMA + ".plan", "operationId": identifier, "configuration": config,
              "configurationSha256": digest(config), "package": bound,
              "bucket": config["tenant"].lower() + ".package.upload", "key": object_key,
              "mode": mode, "apiSources": API_SOURCE}
    with p.project_lock(root):
        remote = root / "remote"
        require(not remote.is_symlink(), "Remote journal cannot be a symlink")
        remote.mkdir(mode=0o700, exist_ok=True)
        directory = remote / identifier
        require(not directory.is_symlink(), "Operation cannot be a symlink")
        directory.mkdir(mode=0o700, exist_ok=True)
        if (directory / "plan.json").exists():
            old = _load(directory, "plan.json")
            require(old == stable, "This operation ID already belongs to a different original plan")
        else:
            p.write_new(directory / "plan.json", p.canonical(stable))
        if (directory / "current.json").exists():
            _read_state(directory, stable)
            return show(root, identifier)
        initial = {"schema": SCHEMA + ".state", "operationId": identifier, "planSha256": digest(stable),
            "revision": -1, "state": "PLANNED", "createdAt": p.utc(), "updatedAt": None,
            "retryAt": None, "lastIssue": None, "actions": {},
            "transfer": {"key": object_key, "bucket": stable["bucket"], "mode": mode,
                         "uploadId": None, "parts": {}, "progressToken": None, "submitted": False},
            "ingest": {"status": None, "processId": None, "processStatus": None},
            "readback": {"totalRecords": bound["includedRecords"], "verifiedRecords": 0,
                         "unresolvedRecords": bound["includedRecords"], "records": {},
                         "folders": {}, "lastObservedAt": None},
            "events": []}
        # Publish initial state under this already-held ordinary workspace lock.
        initial["revision"] = 0
        initial["previousStateSha256"] = None
        initial["updatedAt"] = p.utc()
        raw = p.canonical(initial)
        relative = "states/00000000-" + p.digest(raw) + ".json"
        if not (directory / relative).exists():
            p.write_new(directory / relative, raw)
        _atomic_json(directory / "current.json", {"schema": SCHEMA + ".current", "path": relative,
            "bytes": len(raw), "sha256": p.digest(raw), "revision": 0})
    return show(root, identifier)


def _planned(root, identifier):
    identifier = operation_id(identifier)
    directory = root / "remote" / identifier
    require(directory.is_dir() and not directory.is_symlink(), "Open the original saved upload operation")
    planned = _load(directory, "plan.json")
    require(planned.get("schema") == SCHEMA + ".plan" and planned.get("operationId") == identifier,
            "Unsupported saved upload plan")
    config = validate_configuration(planned["configuration"])
    require(config == planned["configuration"] and digest(config) == planned.get("configurationSha256"),
            "Saved configuration changed")
    return directory, planned


def _summary(root, directory, planned, state):
    rb = state["readback"]
    records = sorted(rb["records"].values(), key=lambda x: x["identifier"])
    next_actions = []
    if state["state"] == "PLANNED":
        next_actions.append("run")
    if state["state"] == "AUTH_REQUIRED":
        next_actions.append("Supply a fresh token in " + planned["configuration"]["accessTokenEnv"] + "; run or refresh")
    if state["state"] == "UPLOAD_UNCERTAIN":
        next_actions.append("Refresh original progress/source readback or reconcile an original upload response")
    if state["state"] not in {"VERIFIED", "PLANNED"}:
        next_actions.append("refresh")
    return {"schema": SCHEMA + ".status", "operationId": planned["operationId"],
            "state": state["state"], "revision": state["revision"], "updatedAt": state["updatedAt"],
            "configuration": clone(planned["configuration"]), "package": clone(planned["package"]),
            "transfer": clone(state["transfer"]), "ingest": clone(state["ingest"]),
            "target": clone(state.get("target")),
            "readback": {**clone(rb), "records": records},
            "nextActions": next_actions, "retryAt": state.get("retryAt"),
            "lastIssue": clone(state.get("lastIssue")), "events": clone(state.get("events", [])),
            "actions": clone(state.get("actions", {})),
            "scope": "Verified records describe retained receiving observations, not continuous repository monitoring."}


def show(package_workspace, operation_id=None):
    root = Path(package_workspace).absolute()
    if operation_id is None:
        remote = root / "remote"
        if not remote.exists():
            return {"schema": SCHEMA + ".operations", "operations": []}
        require(remote.is_dir() and not remote.is_symlink(), "Invalid remote operation directory")
        results = []
        for directory in sorted(remote.iterdir()):
            if directory.is_dir() and not directory.is_symlink() and (directory / "plan.json").exists():
                results.append(show(root, directory.name))
        return {"schema": SCHEMA + ".operations", "operations": results}
    directory, planned = _planned(root, operation_id)
    # Atomic current.json plus immutable state: no network or writer lock.
    state = _read_state(directory, planned)
    return _summary(root, directory, planned, state)


class Slice:
    def __init__(self, path, expected, offset=0, length=None, expected_stamp=None):
        self.path, self.expected = Path(path), expected
        self.offset = offset
        self.length = expected["bytes"] - offset if length is None else length
        require(0 <= offset <= expected["bytes"] and 0 <= self.length <= expected["bytes"] - offset,
                "Invalid original upload byte range")
        self.fd = os.open(self.path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
        try:
            self.before = os.fstat(self.fd)
            require(stat.S_ISREG(self.before.st_mode) and self.before.st_size == expected["bytes"],
                    "Original transfer file changed")
            if expected_stamp is not None:
                require(_stamp(self.before) == expected_stamp, "Upload file changed after source verification")
            self.sha256 = self._range_hash()
            if self.offset == 0 and self.length == expected["bytes"]:
                require(self.sha256 == expected["sha256"], "Original upload bytes differ from the saved package")
        except BaseException:
            os.close(self.fd)
            raise

    def _range_hash(self):
        value, position, remaining = hashlib.sha256(), self.offset, self.length
        while remaining:
            block = os.pread(self.fd, min(CHUNK, remaining), position)
            require(bool(block), "Original transfer ended before its declared size")
            value.update(block)
            position += len(block)
            remaining -= len(block)
        self.check()
        return value.hexdigest()

    def check(self):
        require(_stamp(os.fstat(self.fd)) == _stamp(self.before), "Original transfer changed during use")

    def blocks(self, cancelled):
        remaining, position = self.length, self.offset
        while remaining:
            _cancelled(cancelled)
            block = os.pread(self.fd, min(CHUNK, remaining), position)
            require(bool(block), "Original upload source ended early")
            yield block
            position += len(block)
            remaining -= len(block)
        self.check()

    def close(self):
        os.close(self.fd)


class Context:
    def __init__(self, root, identifier, cancelled=None):
        self.root, self.cancelled = Path(root).absolute(), cancelled
        self.directory, self.planned = _planned(self.root, identifier)
        self.handoff = q.verify_workspace(self.root)
        require(_binding(self.root, self.handoff) == self.planned["package"], "Saved plan source package changed")
        self.config = self.planned["configuration"]
        self.catalog = q.json_member(self.root, "catalog.json")
        self.state = _read_state(self.directory, self.planned)
        self.origin = self.config["origin"]
        self.version = self.config["targetVersion"]
        self.entity_ns = "http://preservica.com/EntityAPI/v" + self.version
        self.xip_ns = "http://preservica.com/XIP/v" + self.version
        self.trace = []
        self.transfer = self.handoff["transfer"]
        source_path = self.root / self.transfer["path"]
        before = source_path.stat()
        require(q.file_digest(source_path) == {
            "bytes": self.transfer["bytes"], "sha256": self.transfer["sha256"]},
            "Original upload archive changed")
        require(_stamp(before) == _stamp(source_path.stat()), "Original archive changed during verification")
        self.source_stamp = _stamp(before)
        require(self.planned["bucket"] == self.config["tenant"].lower() + ".package.upload",
                "Original upload bucket changed")
        require(self.planned["key"] == "commons-" + self.planned["operationId"] + "-"
                + self.transfer["sha256"][:24] + ".zip", "Original object key changed")

    def publish(self):
        _save_state(self.root, self.directory, self.planned, self.state)

    def note(self, kind, **details):
        self.state["events"].append({"at": p.utc(), "kind": kind, **clone(details)})
        self.state["events"] = self.state["events"][-200:]

    def finish(self, state, code=None, retry_at=None):
        self.state["state"] = state
        self.state["retryAt"] = retry_at
        self.state["lastIssue"] = {"code": code, "at": p.utc()} if code else None
        self.publish()

    def api_url(self, value, *, endpoint=None):
        require(isinstance(value, str) and value, "Missing provider API URL")
        absolute = url.urljoin(self.origin + "/", value)
        parsed = url.urlsplit(absolute)
        base = url.urlsplit(self.origin)
        require((parsed.scheme, parsed.hostname, parsed.port) == (base.scheme, base.hostname, base.port)
                and not parsed.username and not parsed.password and not parsed.fragment,
                "Provider API link left the selected authenticated origin")
        require(parsed.path.startswith("/api/") and "\\" not in parsed.path
                and not any(part in {".", ".."} for part in url.unquote(parsed.path).split("/")),
                "Provider API link left the supported API path")
        if endpoint is not None:
            require(parsed.path == endpoint, "Provider pagination changed the original endpoint")
        for name, _ in url.parse_qsl(parsed.query, keep_blank_values=True):
            require(name in SAFE_QUERY, "Provider API link contains an unsupported query field")
        return absolute

    def path(self, name, query=None):
        return name + ("?" + url.urlencode(query) if query else "")

    def object_path(self, query=None):
        name = "/api/s3/buckets/" + url.quote(self.planned["bucket"], safe="") + "/" + url.quote(self.planned["key"], safe="")
        return self.path(name, query)

    def _new_request(self, request):
        with p.project_lock(self.root):
            parent = self.directory / "http"
            parent.mkdir(exist_ok=True, mode=0o700)
            require(not parent.is_symlink(), "HTTP journal cannot be a symlink")
            numbers = [int(x.name.split("-", 1)[0]) for x in parent.iterdir()
                       if x.is_dir() and re.fullmatch(r"[0-9]{8}-[0-9a-f]{16}", x.name)]
            number = max(numbers, default=0) + 1
            require(number < 100000000, "HTTP journal exhausted")
            name = format(number, "08d") + "-" + digest(request)[:16]
            directory = parent / name
            directory.mkdir(mode=0o700)
            p.write_new(directory / "request.json", p.canonical(request))
            p.fsync_dir(parent)
        return directory

    def _save_response(self, directory, receipt, retained):
        with p.project_lock(self.root):
            if retained is not None:
                p.write_new(directory / "response.body", retained)
            p.write_new(directory / "response.json", p.canonical(receipt))
        entry = {"request": directory.relative_to(self.directory).as_posix() + "/request.json",
                 "response": directory.relative_to(self.directory).as_posix() + "/response.json",
                 "requestSha256": receipt["requestSha256"], "responseSha256": digest(receipt)}
        self.trace.append(entry)
        return entry

    def request(self, method, target, *, data=None, headers=None, action=None, download=None, external=False):
        _cancelled(self.cancelled)
        if _future(self.state.get("retryAt")):
            raise Stop("COOLDOWN", "RETAINED_RETRY_AFTER", retry_at=self.state["retryAt"])
        absolute = self.api_url(target) if not external else target
        parsed = url.urlsplit(absolute)
        require(parsed.scheme == "https" or (parsed.scheme == "http" and
                parsed.hostname in {"127.0.0.1", "::1", "localhost"}), "Unsafe content download transport")
        require(not parsed.username and not parsed.password and not parsed.fragment, "Invalid content download URL")
        authenticated = not external
        token = os.environ.get(self.config["accessTokenEnv"]) if authenticated else None
        if authenticated and (not isinstance(token, str) or not token or any(ord(c) < 33 for c in token)):
            raise Stop("AUTH_REQUIRED", "ACCESS_TOKEN_ENVIRONMENT_MISSING")
        safe_headers = dict(headers or {})
        require(not (set(k.lower() for k in safe_headers) & SECRET_HEADERS), "Credentials are not caller headers")
        if isinstance(data, Slice):
            body = {"kind": "original-transfer-range", "path": self.transfer["path"],
                    "transferSha256": self.transfer["sha256"], "offset": data.offset,
                    "bytes": data.length, "sha256": data.sha256}
            length = data.length
        elif data is not None:
            require(isinstance(data, bytes), "Request body must be exact bytes")
            body, length = {"kind": "bytes", "bytes": len(data), "sha256": p.digest(data)}, len(data)
        else:
            body, length = None, 0
        request = {"schema": SCHEMA + ".http-request", "operationId": self.planned["operationId"],
                   "method": method, "url": _safe_url(absolute, self.origin),
                   "urlSha256": p.digest(absolute.encode("utf-8")), "headers": safe_headers,
                   "body": body, "action": action, "createdAt": p.utc(),
                   "authentication": "selected-environment-reference" if authenticated else "none",
                   "downloadExpected": clone(download)}
        directory = self._new_request(request)
        if data is not None and not isinstance(data, Slice):
            with p.project_lock(self.root):
                p.write_new(directory / "request.body", data)
        if action:
            previous = self.state["actions"].get(action)
            attempts = list(previous.get("attempts", [])) if previous else []
            attempts.append(directory.relative_to(self.directory).as_posix())
            self.state["actions"][action] = {"state": "DISPATCHED", "attempts": attempts,
                "request": attempts[-1], "requestSha256": digest(request), "result": None}
            self.state["state"] = "UPLOADING"
            self.state["lastIssue"] = None
            self.publish()
        connection = None
        response, status_code, response_headers = None, None, []
        sent, complete, raw, total, source_sha = False, False, bytearray(), 0, hashlib.sha256()
        error = None
        try:
            constructor = http.client.HTTPSConnection if parsed.scheme == "https" else http.client.HTTPConnection
            options = {"timeout": self.config["requestTimeoutSeconds"]}
            if parsed.scheme == "https":
                options["context"] = ssl.create_default_context()
            connection = constructor(parsed.hostname, parsed.port, **options)
            path = url.urlunsplit(("", "", parsed.path or "/", parsed.query, ""))
            connection.putrequest(method, path, skip_accept_encoding=True)
            connection.putheader("User-Agent", "Commons-Preservica-Receiving/1")
            connection.putheader("Accept", "*/*")
            connection.putheader("Connection", "close")
            if authenticated:
                connection.putheader("Preservica-Access-Token", token)
            for name, value in safe_headers.items():
                require(isinstance(name, str) and isinstance(value, str)
                        and not any(c in name + value for c in "\r\n"), "Invalid outgoing header")
                connection.putheader(name, value)
            if data is not None or method in {"POST", "PUT"}:
                connection.putheader("Content-Length", str(length))
            # Once endheaders starts, a remote side effect cannot be excluded.
            sent = True
            connection.endheaders()
            if isinstance(data, Slice):
                for block in data.blocks(self.cancelled):
                    connection.send(block)
            elif data:
                connection.send(data)
            response = connection.getresponse()
            status_code, response_headers = response.status, response.getheaders()
            limit = download["bytes"] if download and status_code == 200 else self.config["maxResponseBytes"]
            while True:
                _cancelled(self.cancelled)
                block = response.read(min(CHUNK, max(1, limit + 1 - total)))
                if not block:
                    complete = response.length in {None, 0}
                    if not complete:
                        error = "TRUNCATED_CONTENT_LENGTH"
                    break
                source_sha.update(block)
                total += len(block)
                if not (download and status_code == 200):
                    raw.extend(block)
                if total > limit:
                    error = "RESPONSE_BYTE_LIMIT"
                    break
            if isinstance(data, Slice):
                data.check()
        except Stop as exc:
            error = exc.code
        except (OSError, http.client.HTTPException, ssl.SSLError, ValueError) as exc:
            error = type(exc).__name__
        finally:
            if response is not None:
                response.close()
            if connection is not None:
                connection.close()
        for selected_header in ("etag", "preservica-progress-token", "content-length", "location", "retry-after"):
            values = {value for key, value in response_headers if key.lower() == selected_header}
            if len(values) > 1:
                error = "AMBIGUOUS_RESPONSE_HEADERS"
        header_map = _safe_headers(response_headers, self.origin, token)
        source_descriptor = {"bytes": total, "sha256": source_sha.hexdigest(), "complete": complete}
        retained = None
        redacted = False
        if not (download and status_code == 200):
            retained, redacted = _safe_body(bytes(raw), self.origin, token)
        receipt = {"schema": SCHEMA + ".http-response", "requestSha256": digest(request),
                   "status": status_code, "headers": header_map, "completedAt": p.utc(),
                   "dispatchStarted": sent, "body": source_descriptor, "error": error,
                   "retainedBody": None if retained is None else {
                       "path": "response.body", "bytes": len(retained), "sha256": p.digest(retained),
                       "redacted": redacted},
                   "download": clone(download)}
        entry = self._save_response(directory, receipt, retained)
        result = {"receipt": receipt, "raw": bytes(raw), "entry": entry, "directory": directory,
                  "headers": dict((k.lower(), v) for k, v in response_headers),
                  "body": source_descriptor}
        if status_code == 401:
            raise Stop("AUTH_REQUIRED", "PROVIDER_REQUIRES_FRESH_TOKEN")
        if status_code == 429 or (status_code == 503 and header_map.get("retry-after")):
            raise Stop("COOLDOWN", "PROVIDER_RETRY_AFTER", retry_at=_retry_at(header_map.get("retry-after")))
        if error == "CANCELLED_BETWEEN_REQUESTS":
            raise Stop("INTERRUPTED", error)
        return result

    def retained_response(self, relative):
        require(isinstance(relative, str) and re.fullmatch(r"http/[0-9]{8}-[0-9a-f]{16}", relative),
                "Invalid original request directory")
        directory = self.directory / relative
        request = _load(directory, "request.json")
        if not (directory / "response.json").exists():
            return None
        receipt = _load(directory, "response.json")
        require(receipt.get("schema") == SCHEMA + ".http-response"
                and receipt.get("requestSha256") == digest(request), "Retained HTTP response binding changed")
        body = receipt.get("retainedBody")
        raw = b""
        if body is not None:
            require(body.get("path") == "response.body", "Invalid retained response body path")
            raw = p.read_regular(directory, "response.body", self.config["maxResponseBytes"] + 1)
            require(len(raw) == body.get("bytes") and p.digest(raw) == body.get("sha256"),
                    "Retained response bytes changed")
        return {"receipt": receipt, "raw": raw, "headers": receipt["headers"],
                "directory": directory, "body": receipt["body"],
                "entry": {"request": relative + "/request.json", "response": relative + "/response.json",
                          "requestSha256": digest(request), "responseSha256": digest(receipt)}}

    def get(self, target, *, missing=False, endpoint=None):
        if endpoint is not None:
            target = self.api_url(target, endpoint=endpoint)
        result = self.request("GET", target)
        receipt = result["receipt"]
        if receipt["status"] == 404 and missing and receipt["body"]["complete"]:
            return None
        if receipt["status"] != 200 or not receipt["body"]["complete"] or receipt["error"]:
            raise Unresolved("PROVIDER_READ_UNAVAILABLE", details={"status": receipt["status"],
                                                               "response": result["entry"]})
        return result

    def get_xml(self, target, *, missing=False, endpoint=None):
        result = self.get(target, missing=missing, endpoint=endpoint)
        return None if result is None else (_xml(result["raw"]), result)

    def perform(self, name, method, target, parser, *, data=None, headers=None, repeatable=False):
        retained = self.state["actions"].get(name)
        if retained and retained["state"] == "CONFIRMED":
            if retained.get("adoption"):
                old = _adopted_response(self, retained["adoption"])
            else:
                old = self.retained_response(retained["request"])
                require(old is not None, "Confirmed original response is missing")
                if retained.get("response"):
                    require(old["entry"] == retained["response"], "Confirmed response identity changed")
            checked = parser(old)
            require(checked == retained["result"], "Confirmed response differs from its original source")
            return clone(checked)
        if retained:
            old = self.retained_response(retained["request"])
            if old:
                try:
                    result = parser(old)
                    self.state["actions"][name].update({"state": "CONFIRMED", "result": result,
                                                       "response": old["entry"]})
                    self.publish()
                    return clone(result)
                except Unresolved:
                    status = old["receipt"]["status"]
                    rejection = old["body"]["complete"] and status in {401, 429}
                    never_sent = not old["receipt"]["dispatchStarted"]
            else:
                rejection, never_sent = False, False
            if not repeatable and not (old and (rejection or never_sent)):
                self.state["actions"][name]["state"] = "UNCERTAIN"
                self.publish()
                raise Stop("UPLOAD_UNCERTAIN", "ORIGINAL_" + name.upper() + "_RESPONSE_REQUIRED")
        response = self.request(method, target, data=data, headers=headers, action=name)
        try:
            result = parser(response)
        except Unresolved as exc:
            self.state["actions"][name].update({"state": "UNCERTAIN", "response": response["entry"]})
            self.publish()
            raise Stop("UPLOAD_UNCERTAIN", exc.code)
        self.state["actions"][name].update({"state": "CONFIRMED", "result": result, "response": response["entry"]})
        self.publish()
        return clone(result)

    def evidence(self, name, value):
        value = _safe_value(value, self.origin, os.environ.get(self.config["accessTokenEnv"]))
        raw = p.canonical(value)
        relative = "evidence/" + name + "-" + p.digest(raw) + ".json"
        with p.project_lock(self.root):
            _new_json(self.directory / relative, value)
        return {"path": relative, "bytes": len(raw), "sha256": p.digest(raw)}

    def summary(self):
        return _summary(self.root, self.directory, self.planned, self.state)


def _successful(result, codes=(200,)):
    receipt = result["receipt"]
    if receipt["status"] not in codes or not receipt["body"]["complete"] or receipt.get("error"):
        raise Unresolved("ORIGINAL_RESPONSE_NOT_SUCCESSFUL", details={"status": receipt["status"]})
    return receipt


def _progress_token(result, *, etag=None):
    header = result["headers"].get("preservica-progress-token")
    candidate = None
    if etag and "-progressToken-" in etag:
        candidate = etag.strip('"').rsplit("-progressToken-", 1)[1]
    if header and candidate and header != candidate:
        raise Unresolved("CONFLICTING_PROGRESS_TOKENS")
    value = header or candidate
    if value is not None:
        require(isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,239}", value),
                "Unsupported progress token representation")
    return value


def _parse_init(context, result):
    _successful(result)
    document = _xml(result["raw"])
    if document.tag != "{" + S3_NS + "}InitiateMultipartUploadResult":
        raise Unresolved("MULTIPART_INIT_RESULT_MISSING")
    bucket, key, upload_id = (_text(document, x, S3_NS) for x in ("Bucket", "Key", "UploadId"))
    if bucket != context.planned["bucket"] or key != context.planned["key"]:
        raise Unresolved("MULTIPART_ORIGINAL_TARGET_MISMATCH")
    require(isinstance(upload_id, str) and 1 <= len(upload_id) <= 2048
            and not any(ord(c) < 33 for c in upload_id), "Invalid original multipart upload ID")
    return {"bucket": bucket, "key": key, "uploadId": upload_id,
            "observedAt": result["receipt"]["completedAt"]}


def _parse_part(context, number, part_sha, part_bytes, result):
    _successful(result)
    etag = result["headers"].get("etag")
    if not isinstance(etag, str) or not etag or len(etag) > 4096 or any(ord(c) < 32 for c in etag):
        raise Unresolved("ORIGINAL_PART_ETAG_MISSING")
    return {"partNumber": number, "etag": etag, "bytes": part_bytes, "sha256": part_sha,
            "uploadId": context.state["transfer"]["uploadId"],
            "observedAt": result["receipt"]["completedAt"]}


def _parse_complete(context, result):
    _successful(result)
    document = _xml(result["raw"])
    if document.tag != "{" + S3_NS + "}CompleteMultipartUploadResult":
        raise Unresolved("COMPLETE_RESULT_MISSING_OR_ERROR")
    bucket, key = (_text(document, x, S3_NS) for x in ("Bucket", "Key"))
    if bucket != context.planned["bucket"] or key != context.planned["key"]:
        raise Unresolved("COMPLETION_ORIGINAL_TARGET_MISMATCH")
    etag = _text(document, "ETag", S3_NS)
    if not etag:
        raise Unresolved("COMPLETION_ETAG_MISSING")
    return {"key": key, "bucket": bucket, "etag": etag, "progressToken": _progress_token(result, etag=etag),
            "uploadId": context.state["transfer"]["uploadId"],
            "observedAt": result["receipt"]["completedAt"]}


def _parse_single(context, result):
    _successful(result)
    if result["raw"].lstrip().startswith(b"<"):
        document = _xml(result["raw"])
        if _local(document) == "Error":
            raise Unresolved("SINGLE_UPLOAD_PROVIDER_ERROR")
    etag = result["headers"].get("etag")
    if not etag:
        raise Unresolved("SINGLE_UPLOAD_ETAG_MISSING")
    return {"key": context.planned["key"], "bucket": context.planned["bucket"], "etag": etag,
            "progressToken": _progress_token(result, etag=etag),
            "observedAt": result["receipt"]["completedAt"]}


def _entity(context, entity_type, entity_ref):
    entity_ref = reference(entity_ref, "provider entity")
    path = "/api/entity/" + PATHS[entity_type] + "/" + entity_ref
    value = context.get_xml(path, missing=True)
    if value is None:
        raise Unresolved("ENTITY_NOT_YET_AVAILABLE", details={"entityType": entity_type, "entityRef": entity_ref})
    document, response = value
    found = _text(document, "Ref", context.xip_ns)
    if found != entity_ref:
        raise Unresolved("ENTITY_IDENTITY_MISMATCH", details={"requested": entity_ref, "returned": found})
    parent_text = _text(document, "Parent", context.xip_ns)
    parent = reference(parent_text, "provider parent") if parent_text else None
    return {"type": entity_type, "ref": entity_ref, "parent": parent,
            "title": _text(document, "Title", context.xip_ns),
            "description": _text(document, "Description", context.xip_ns),
            "securityTag": _text(document, "SecurityTag", context.xip_ns),
            "document": document, "response": response, "path": path}


def _preflight(context):
    document, response = context.get_xml("/api/entity/versiondetails/version")
    observed = _text(document, "CurrentVersion")
    if version(observed) != context.config["targetVersion"]:
        raise Unresolved("SELECTED_TARGET_VERSION_MISMATCH", details={"observedVersion": observed})
    parent = None
    if context.config["parentRef"]:
        parent = _entity(context, "SO", context.config["parentRef"])
    context.state["target"] = {"version": observed, "versionResponse": response["entry"],
                               "parentRef": context.config["parentRef"],
                               "parentResponse": parent["response"]["entry"] if parent else None,
                               "observedAt": p.utc()}
    context.publish()


def _empty_target(context):
    if context.state.get("initialTargetObservation"):
        return
    # HEAD only checks the original unique upload key. It is not entity readback.
    response = context.request("HEAD", context.object_path())
    receipt = response["receipt"]
    if receipt["status"] == 404 and receipt["body"]["complete"] and not receipt["error"]:
        context.state["initialTargetObservation"] = {"state": "ABSENT", "response": response["entry"],
                                                     "observedAt": receipt["completedAt"]}
        context.publish()
        return
    if receipt["status"] == 200:
        raise Stop("UPLOAD_UNCERTAIN", "ORIGINAL_OBJECT_KEY_ALREADY_EXISTS")
    raise Unresolved("UPLOAD_TARGET_PRECHECK_UNAVAILABLE", details={"status": receipt["status"]})


def _complete_body(parts):
    document = ET.Element("CompleteMultipartUpload")
    for part in sorted(parts, key=lambda x: x["partNumber"]):
        item = ET.SubElement(document, "Part")
        ET.SubElement(item, "PartNumber").text = str(part["partNumber"])
        ET.SubElement(item, "ETag").text = part["etag"]
    return ET.tostring(document, encoding="utf-8", xml_declaration=True)


def _upload(context):
    if context.state["transfer"]["submitted"] or context.state["state"] == "VERIFIED":
        return
    _preflight(context)
    _empty_target(context)
    headers = {"Content-Type": "application/zip"}
    if context.config["parentRef"]:
        headers["x-amz-meta-structuralobjectreference"] = context.config["parentRef"]
    transfer_path = context.root / context.transfer["path"]
    expected = {"bytes": context.transfer["bytes"], "sha256": context.transfer["sha256"]}
    if context.planned["mode"] == "single":
        stream = Slice(transfer_path, expected, expected_stamp=context.source_stamp)
        try:
            result = context.perform("single", "PUT", context.object_path(),
                                     lambda value: _parse_single(context, value), data=stream, headers=headers)
        finally:
            stream.close()
    else:
        if not context.state["transfer"]["uploadId"]:
            initialized = context.perform("init", "POST", context.object_path([("uploads", "")]),
                                          lambda value: _parse_init(context, value), data=b"", headers=headers)
            context.state["transfer"]["uploadId"] = initialized["uploadId"]
            context.publish()
        upload_id = context.state["transfer"]["uploadId"]
        parts, offset, number = [], 0, 1
        while offset < expected["bytes"]:
            _cancelled(context.cancelled)
            length = min(context.config["partBytes"], expected["bytes"] - offset)
            stream = Slice(transfer_path, expected, offset, length, expected_stamp=context.source_stamp)
            try:
                part = context.perform("part-" + str(number), "PUT",
                    context.object_path([("uploadId", upload_id), ("partNumber", str(number))]),
                    lambda value, n=number, h=stream.sha256, size=length: _parse_part(context, n, h, size, value),
                    data=stream, headers={"Content-Type": "application/octet-stream"}, repeatable=True)
            finally:
                stream.close()
            require(part["uploadId"] == upload_id and part["partNumber"] == number
                    and part["bytes"] == length, "Original multipart selection changed")
            parts.append(part)
            context.state["transfer"]["parts"][str(number)] = part
            context.publish()
            offset += length
            number += 1
        require(len(parts) <= 10000, "Multipart upload exceeds the supported part count")
        body = _complete_body(parts)
        result = context.perform("complete", "POST", context.object_path([("uploadId", upload_id)]),
                                 lambda value: _parse_complete(context, value), data=body,
                                 headers={"Content-Type": "application/xml"})
    context.state["transfer"]["submitted"] = True
    if result.get("progressToken"):
        context.state["transfer"]["progressToken"] = result["progressToken"]
    context.state["transfer"]["completion"] = result
    context.state["state"] = "INGESTING"
    context.note("ORIGINAL_UPLOAD_RESPONSE_CONFIRMED", key=context.planned["key"])
    context.publish()


def _head_progress(context):
    if context.state["transfer"]["progressToken"]:
        return
    if not context.state["actions"] and not context.state.get("initialTargetObservation"):
        return
    response = context.request("HEAD", context.object_path())
    receipt = response["receipt"]
    if receipt["status"] != 200 or not receipt["body"]["complete"] or receipt["error"]:
        return
    token = _progress_token(response, etag=response["headers"].get("etag"))
    if token:
        context.state["transfer"]["progressToken"] = token
        context.state["transfer"]["progressObservation"] = {
            "kind": "ORIGINAL_OBJECT_HEAD", "response": response["entry"],
            "scope": "Progress observed on this original unique key; content is verified separately."}
        context.publish()


def _observe_progress(context):
    token = context.state["transfer"]["progressToken"]
    if not token:
        return
    response = context.get_xml("/api/entity/progress/" + url.quote(token, safe=""), missing=True)
    if response is None:
        context.state["ingest"].update({"status": "UNKNOWN", "lastObservedAt": p.utc(),
                                        "issue": "ORIGINAL_PROGRESS_TOKEN_NOT_AVAILABLE"})
        context.publish()
        return
    document, result = response
    observed = _text(document, "Status", STATUS_NS)
    if observed not in PROGRESS:
        raise Unresolved("UNSUPPORTED_PROGRESS_STATUS", details={"status": observed})
    context.state["ingest"].update({"status": observed, "lastObservedAt": result["receipt"]["completedAt"],
                                    "progressResponse": result["entry"], "issue": None})
    context.publish()


def _paged_xml(context, target, tag, *, endpoint=None):
    original = url.urlsplit(context.api_url(target)).path
    endpoint = endpoint or original
    bound_query = {k: v for k, v in url.parse_qsl(url.urlsplit(context.api_url(target)).query)
                   if k not in {"start", "max"}}
    seen, values, total = set(), [], None
    while target:
        current = context.api_url(target, endpoint=endpoint)
        selected_query = {k: v for k, v in url.parse_qsl(url.urlsplit(current).query)
                          if k not in {"start", "max"}}
        if selected_query != bound_query:
            raise Unresolved("ENTITY_PAGINATION_SOURCE_SELECTION_CHANGED")
        if current in seen or len(seen) >= 10000:
            raise Unresolved("ENTITY_PAGINATION_LOOP_OR_LIMIT")
        seen.add(current)
        result = context.get_xml(current, missing=True, endpoint=endpoint)
        if result is None:
            return []
        document, _ = result
        values.extend(document.findall(".//{" + context.entity_ns + "}" + tag))
        count = _text(document, "TotalResults", context.entity_ns)
        if count is not None:
            require(re.fullmatch(r"[0-9]+", count), "Invalid provider total")
            if total is not None and total != int(count):
                raise Unresolved("ENTITY_PAGINATION_TOTAL_CHANGED")
            total = int(count)
        next_url = _text(document, "Next", context.entity_ns)
        target = next_url if next_url else None
    if total is not None and len(values) != total:
        raise Unresolved("ENTITY_PAGINATION_INCOMPLETE")
    return values


def _lookup(context, source_id, entity_type):
    target = context.path("/api/entity/entities/by-identifier", [("type", "SourceID"), ("value", source_id)])
    values = _paged_xml(context, target, "Entity")
    exact = {(x.get("type"), x.get("ref")) for x in values}
    if not exact:
        raise Unresolved("SOURCE_ID_NOT_YET_AVAILABLE", details={"sourceId": source_id})
    if len(exact) != 1 or next(iter(exact))[0] != entity_type:
        raise Unresolved("SOURCE_ID_AMBIGUOUS", details={"sourceId": source_id, "matches": len(exact)})
    return _entity(context, entity_type, next(iter(exact))[1])


def _identifiers(context, entity):
    target = entity["path"] + "/identifiers"
    visited, identifiers = set(), []
    while target:
        current = context.api_url(target, endpoint=entity["path"] + "/identifiers")
        if current in visited or len(visited) >= 10000:
            raise Unresolved("IDENTIFIER_PAGINATION_LOOP")
        visited.add(current)
        document, _ = context.get_xml(current)
        for item in document.findall(".//{" + context.xip_ns + "}Identifier"):
            kind, value = (_text(item, field, context.xip_ns) for field in ("Type", "Value"))
            identifiers.append({"type": kind, "value": value, "apiId": _text(item, "ApiId", context.xip_ns)})
        target = _text(document, "Next", context.entity_ns)
    return identifiers


def _metadata(context, entity, expected):
    fragments = entity["document"].findall(".//{" + context.entity_ns + "}Metadata/{" + context.entity_ns + "}Fragment")
    candidates = []
    for fragment in fragments:
        if fragment.get("schema") not in {q.OAI_DC_NS, q.DC_NS}:
            continue
        require(fragment.text is not None, "Metadata fragment has no URL")
        document, response = context.get_xml(context.api_url(fragment.text))
        content = document.find(".//{" + context.xip_ns + "}Content")
        dc = None
        if content is not None:
            children = list(content)
            if len(children) == 1 and children[0].tag == "{" + q.OAI_DC_NS + "}dc":
                dc = children[0]
        if dc is None:
            continue
        actual = {}
        for element in dc:
            if not isinstance(element.tag, str) or not element.tag.startswith("{" + q.DC_NS + "}"):
                raise Unresolved("UNEXPECTED_DUBLIN_CORE_FIELD")
            field = _local(element)
            actual.setdefault(field, []).append("".join(element.itertext()))
        same = set(actual) == set(expected) and all(Counter(actual[k]) == Counter(expected[k]) for k in expected)
        if same:
            candidates.append({"fragment": _safe_url(fragment.text, context.origin), "response": response["entry"],
                               "reviewedDcSha256": digest(expected), "observedDcSha256": digest(actual)})
    if len(candidates) != 1:
        raise Unresolved("REVIEWED_METADATA_NOT_UNIQUELY_VERIFIED", details={"matchingFragments": len(candidates)})
    return candidates[0]


def _check_entity(context, entity, *, parent, title, source_id, identifier=None):
    if entity["parent"] != parent:
        raise Unresolved("ENTITY_PARENT_MISMATCH", details={"entityRef": entity["ref"],
                                                         "expectedParent": parent, "actualParent": entity["parent"]})
    if entity["title"] != title:
        raise Unresolved("ENTITY_TITLE_MISMATCH", details={"entityRef": entity["ref"]})
    configured_security = context.handoff["settings"]["securityTag"]
    if configured_security is not None and entity["securityTag"] != configured_security:
        raise Unresolved("ENTITY_SECURITY_TAG_MISMATCH", details={"entityRef": entity["ref"]})
    identifiers = _identifiers(context, entity)
    if not any(x["type"] == "SourceID" and x["value"] == source_id for x in identifiers):
        raise Unresolved("ORIGINAL_SOURCE_ID_NOT_RETAINED", details={"entityRef": entity["ref"]})
    if identifier and not any(x["value"] == identifier for x in identifiers):
        raise Unresolved("ORIGINAL_RESEARCH_IDENTIFIER_NOT_RETAINED", details={"entityRef": entity["ref"]})
    return {"entityType": entity["type"], "entityRef": entity["ref"], "parentRef": entity["parent"],
            "title": entity["title"], "securityTag": entity["securityTag"], "sourceId": source_id,
            "identifiers": identifiers, "entityResponse": entity["response"]["entry"]}


def _download(context, target, expected):
    require(isinstance(target, str) and target, "Missing provider content URL")
    current = url.urljoin(context.origin + "/", target)
    initial = url.urlsplit(current)
    require(initial.scheme == "https" or (initial.scheme == "http" and
            initial.hostname in {"127.0.0.1", "::1", "localhost"}), "Unsafe provider content URL")
    require(not initial.username and not initial.password and not initial.fragment, "Invalid provider content URL")
    visited = set()
    for _ in range(6):
        if current in visited:
            raise Unresolved("CONTENT_REDIRECT_LOOP")
        visited.add(current)
        parsed, base = url.urlsplit(current), url.urlsplit(context.origin)
        external = (parsed.scheme, parsed.hostname, parsed.port) != (base.scheme, base.hostname, base.port)
        result = context.request("GET", current, download=expected, external=external)
        receipt = result["receipt"]
        if receipt["status"] in {301, 302, 303, 307, 308}:
            if not receipt["body"]["complete"] or receipt["error"]:
                raise Unresolved("CONTENT_REDIRECT_RESPONSE_INCOMPLETE")
            location = result["headers"].get("location")
            if not location:
                raise Unresolved("CONTENT_REDIRECT_LOCATION_MISSING")
            next_url = url.urljoin(current, location)
            next_parts = url.urlsplit(next_url)
            require(next_parts.scheme == "https" or (
                next_parts.scheme == "http" and parsed.scheme == "http"
                and next_parts.hostname in {"127.0.0.1", "::1", "localhost"}),
                "Content redirect downgraded transport")
            require(not next_parts.username and not next_parts.password and not next_parts.fragment,
                    "Unsafe content redirect")
            current = next_url
            continue
        _successful(result)
        if result["body"]["bytes"] != expected["bytes"] or result["body"]["sha256"] != expected["sha256"]:
            raise Unresolved("ORIGINAL_CONTENT_BYTES_DIFFER", details={"expected": expected,
                "actual": {"bytes": result["body"]["bytes"], "sha256": result["body"]["sha256"]}})
        return {"bytes": expected["bytes"], "sha256": expected["sha256"],
                "response": result["entry"], "observedAt": receipt["completedAt"],
                "scope": "Full returned original content was streamed and hashed; credentials were not forwarded across origins."}
    raise Unresolved("CONTENT_REDIRECT_LIMIT")


def _content(context, entity, row):
    document, _ = context.get_xml(entity["path"] + "/representations")
    representations = document.findall(".//{" + context.entity_ns + "}Representation")
    originals = []
    for representation in representations:
        if representation.get("type") != "Preservation":
            continue
        if not representation.text:
            raise Unresolved("PRESERVATION_REPRESENTATION_URL_MISSING")
        rep_url = context.api_url(representation.text)
        rep_doc, _ = context.get_xml(rep_url)
        refs = rep_doc.findall(".//{" + context.xip_ns + "}Representation/{" + context.xip_ns
                               + "}ContentObjects/{" + context.xip_ns + "}ContentObject")
        for ref in refs:
            content_object = _entity(context, "CO", ref.text)
            if content_object["parent"] != entity["ref"]:
                raise Unresolved("CONTENT_OBJECT_PARENT_MISMATCH")
            generations, _ = context.get_xml(content_object["path"] + "/generations")
            for link in generations.findall(".//{" + context.entity_ns + "}Generation"):
                require(link.text is not None, "Generation has no URL")
                generation_url = context.api_url(link.text)
                generation, _ = context.get_xml(generation_url)
                original = generation.find(".//{" + context.xip_ns + "}Generation")
                if original is None or original.get("original", "").lower() not in {"true", "1"}:
                    continue
                for bit in generation.findall(".//{" + context.entity_ns + "}Bitstreams/{" + context.entity_ns + "}Bitstream"):
                    require(bit.text is not None, "Original bitstream has no URL")
                    bit_url = context.api_url(bit.text)
                    stream, response = context.get_xml(bit_url)
                    filename = _text(stream, "Filename", context.xip_ns)
                    size = _text(stream, "FileSize", context.xip_ns)
                    require(size is not None and re.fullmatch(r"[0-9]+", size), "Invalid original bitstream size")
                    fixities = []
                    for fixity in stream.findall(".//{" + context.xip_ns + "}Fixity"):
                        algorithm = _text(fixity, "FixityAlgorithmRef", context.xip_ns)
                        value = _text(fixity, "FixityValue", context.xip_ns)
                        # The maintained entity model exposes these two XIP children;
                        # their values are retained without assuming an ETag algorithm.
                        if algorithm is None or value is None:
                            children = list(fixity)
                            if len(children) == 2:
                                algorithm, value = children[0].text, children[1].text
                        fixities.append({"algorithm": algorithm, "value": value})
                    target = _text(stream, "Content", context.entity_ns)
                    originals.append({"filename": filename, "bytes": int(size), "fixities": fixities,
                        "contentUrl": target, "contentObjectRef": content_object["ref"],
                        "representationUrl": _safe_url(rep_url, context.origin),
                        "generationUrl": _safe_url(generation_url, context.origin),
                        "bitstreamUrl": _safe_url(bit_url, context.origin), "response": response["entry"]})
    expected_name = row["nativePath"].rsplit("/", 1)[1]
    if len(originals) != 1 or originals[0]["filename"] != expected_name:
        raise Unresolved("ORIGINAL_CONTENT_STRUCTURE_MISMATCH", details={"originalFiles": len(originals)})
    original = originals[0]
    if original["bytes"] != row["payload"]["bytes"]:
        raise Unresolved("ORIGINAL_CONTENT_SIZE_MISMATCH")
    hashes = [x["value"].lower() for x in original["fixities"]
              if isinstance(x["algorithm"], str) and isinstance(x["value"], str)
              and re.sub(r"[^A-Z0-9]", "", x["algorithm"].upper()) == "SHA256"]
    if not hashes or set(hashes) != {row["payload"]["sha256"]}:
        raise Unresolved("ORIGINAL_REPOSITORY_FIXITY_MISMATCH")
    if not original["contentUrl"]:
        raise Unresolved("ORIGINAL_CONTENT_DOWNLOAD_UNAVAILABLE")
    downloaded = _download(context, original.pop("contentUrl"), row["payload"])
    return {**original, "download": downloaded}


def _verify_folders(context):
    cached = context.state["readback"]["folders"]
    for value in cached.values():
        descriptor = value["evidence"]
        raw = p.read_regular(context.directory, descriptor["path"], MAX_STATE)
        require(p.digest(raw) == descriptor["sha256"] and len(raw) == descriptor["bytes"],
                "Retained folder verification changed")
    if "package" not in cached:
        start = len(context.trace)
        folder = _lookup(context, context.handoff["packageSourceId"], "SO")
        checked = _check_entity(context, folder, parent=context.config["parentRef"],
                               title=context.handoff["settings"]["title"],
                               source_id=context.handoff["packageSourceId"])
        settings = context.handoff["settings"]
        dc = {"title": [settings["title"]], "description": [
                settings["description"], "Original bibliographic metadata; no paper full text is included."],
              "type": ["Collection"], "identifier": [context.handoff["packageSourceId"]],
              "source": ["urn:sha256:" + context.handoff["source"]["manifestSha256"]], "rights": [p.LICENSE]}
        checked["metadata"] = _metadata(context, folder, dc)
        checked.update({"schema": SCHEMA + ".folder-readback", "kind": "package",
                        "observedAt": p.utc(), "http": context.trace[start:]})
        descriptor = context.evidence("package-folder", checked)
        cached["package"] = {"entityRef": folder["ref"], "parentRef": folder["parent"],
                             "observedAt": checked["observedAt"], "evidence": descriptor}
        context.publish()
    if "records" not in cached:
        start = len(context.trace)
        folder = _lookup(context, context.handoff["recordsFolderSourceId"], "SO")
        checked = _check_entity(context, folder, parent=cached["package"]["entityRef"],
                               title="Research records", source_id=context.handoff["recordsFolderSourceId"])
        checked.update({"schema": SCHEMA + ".folder-readback", "kind": "records",
                        "observedAt": p.utc(), "http": context.trace[start:]})
        descriptor = context.evidence("records-folder", checked)
        cached["records"] = {"entityRef": folder["ref"], "parentRef": folder["parent"],
                             "observedAt": checked["observedAt"], "evidence": descriptor}
        context.publish()
    return cached["records"]["entityRef"]


def _verified_entry(context, row, parent):
    start = len(context.trace)
    entity = _lookup(context, row["sourceId"], "IO")
    checked = _check_entity(context, entity, parent=parent,
                           title=" | ".join(row["reviewedDc"].get("title", [])),
                           source_id=row["sourceId"], identifier=row["identifier"])
    metadata = _metadata(context, entity, row["reviewedDc"])
    content = _content(context, entity, row)
    record = {"schema": SCHEMA + ".record-readback", "operationId": context.planned["operationId"],
              "packageId": context.handoff["id"], "identifier": row["identifier"],
              "sourceId": row["sourceId"], "nativePath": row["nativePath"],
              "expected": clone(row["payload"]), "reviewedDcSha256": digest(row["reviewedDc"]),
              "entity": checked, "metadata": metadata, "content": content,
              "observedAt": p.utc(), "http": context.trace[start:]}
    descriptor = context.evidence(row["identifier"].rsplit("/", 1)[1], record)
    return {"identifier": row["identifier"], "sourceId": row["sourceId"], "status": "VERIFIED",
            "entityRef": entity["ref"], "parentRef": entity["parent"], "bytes": row["payload"]["bytes"],
            "sha256": row["payload"]["sha256"], "observedAt": record["observedAt"], "evidence": descriptor}


def _verify_records(context):
    try:
        parent = _verify_folders(context)
    except Unresolved as exc:
        context.state["readback"]["folderIssue"] = {"code": exc.code, "details": clone(exc.details), "at": p.utc()}
        context.publish()
        return
    context.state["readback"]["folderIssue"] = None
    selected = [row for row in context.catalog["records"] if row["include"]]
    saved = context.state["readback"]["records"]
    context.state["state"] = "VERIFYING"
    context.publish()
    pending = 0
    for row in selected:
        _cancelled(context.cancelled)
        original = saved.get(row["identifier"])
        if original and original.get("status") == "VERIFIED":
            descriptor = original["evidence"]
            raw = p.read_regular(context.directory, descriptor["path"], MAX_STATE)
            require(len(raw) == descriptor["bytes"] and p.digest(raw) == descriptor["sha256"],
                    "Retained record verification changed")
            value = p.parse_json(raw)
            require(value["identifier"] == row["identifier"] and value["sourceId"] == row["sourceId"]
                    and value["expected"] == row["payload"] and value["reviewedDcSha256"] == digest(row["reviewedDc"]),
                    "Verified record belongs to another original source")
            continue
        try:
            saved[row["identifier"]] = _verified_entry(context, row, parent)
        except Unresolved as exc:
            saved[row["identifier"]] = {"identifier": row["identifier"], "sourceId": row["sourceId"],
                "status": "UNRESOLVED", "code": exc.code, "details": clone(exc.details), "observedAt": p.utc()}
        pending += 1
        if pending >= context.config["readbackBatchSize"]:
            _readback_counts(context)
            context.publish()
            pending = 0
    _readback_counts(context)
    context.publish()


def _readback_counts(context):
    readback = context.state["readback"]
    readback["verifiedRecords"] = sum(value.get("status") == "VERIFIED" for value in readback["records"].values())
    readback["unresolvedRecords"] = readback["totalRecords"] - readback["verifiedRecords"]
    readback["lastObservedAt"] = p.utc()


def _monitor(context):
    selected = context.state["ingest"].get("processId")
    if not selected:
        return
    start = len(context.trace)
    target = "/api/processmonitor/monitors"
    visited, matches, complete = set(), [], True
    while target:
        absolute = context.api_url(target, endpoint="/api/processmonitor/monitors")
        if absolute in visited or len(visited) >= 1000:
            raise Unresolved("PROCESS_MONITOR_PAGINATION_LOOP")
        visited.add(absolute)
        response = context.get(absolute)
        value = p.parse_json(response["raw"]).get("value")
        require(isinstance(value, dict) and isinstance(value.get("monitors"), list), "Invalid process-monitor response")
        matches.extend(row for row in value["monitors"] if str(row.get("mappedId")) == selected)
        paging = value.get("paging")
        if isinstance(paging, dict):
            target = paging.get("next")
            if not target and isinstance(paging.get("totalResults"), int):
                # A list without an explicit paging contract is never used to prove absence.
                complete = False
        else:
            target, complete = None, False
    if len(matches) != 1:
        context.state["ingest"].update({"processStatus": None, "processObservation": {
            "selectedId": selected, "matches": len(matches), "listExhaustive": complete,
            "issue": "SELECTED_MONITOR_NOT_UNIQUELY_RETURNED", "observedAt": p.utc()}})
        context.publish()
        return
    messages, target, visited, expected_total = [], context.path(
        "/api/processmonitor/messages", [("monitor", selected), ("start", "0"), ("max", "100")]), set(), None
    while target:
        absolute = context.api_url(target, endpoint="/api/processmonitor/messages")
        parsed = dict(url.parse_qsl(url.urlsplit(absolute).query))
        if parsed.get("monitor") != selected or absolute in visited or len(visited) >= 10000:
            raise Unresolved("PROCESS_MESSAGE_SELECTION_OR_PAGINATION_CHANGED")
        visited.add(absolute)
        response = context.get(absolute)
        value = p.parse_json(response["raw"]).get("value")
        require(isinstance(value, dict) and isinstance(value.get("messages"), list), "Invalid process message response")
        for message in value["messages"]:
            if str(message.get("mappedMonitorId")) != selected:
                raise Unresolved("PROCESS_MESSAGE_MONITOR_MISMATCH")
            messages.append(message)
        paging = value.get("paging", {})
        require(isinstance(paging, dict), "Invalid process message paging")
        total = paging.get("totalResults")
        if total is not None:
            require(isinstance(total, int) and not isinstance(total, bool) and total >= 0,
                    "Invalid process message total")
            if expected_total is not None and expected_total != total:
                raise Unresolved("PROCESS_MESSAGE_TOTAL_CHANGED")
            expected_total = total
        target = paging.get("next")
    if expected_total is not None and len(messages) != expected_total:
        raise Unresolved("PROCESS_MESSAGE_PAGINATION_INCOMPLETE")
    record = {"schema": SCHEMA + ".process-observation", "selectedId": selected,
              "monitor": matches[0], "messages": messages, "observedAt": p.utc(), "http": context.trace[start:],
              "association": "Explicit operator-selected process observation; not a progress-token or permanent entity link.",
              "idScope": "Monitor mapped IDs can change between product releases."}
    descriptor = context.evidence("process-observation", record)
    status = matches[0].get("status", matches[0].get("state"))
    context.state["ingest"].update({"processStatus": status, "processObservation": descriptor})
    context.publish()


def _observe(context):
    _preflight(context)
    _head_progress(context)
    _observe_progress(context)
    if context.state["ingest"].get("processId"):
        try:
            _monitor(context)
        except Unresolved as exc:
            context.state["ingest"]["processIssue"] = {"code": exc.code, "details": clone(exc.details), "at": p.utc()}
            context.publish()
    _verify_records(context)
    rb = context.state["readback"]
    status = context.state["ingest"].get("status")
    if status in FAILED:
        context.finish("INGEST_FAILED", "ORIGINAL_PROGRESS_" + status)
    elif rb["verifiedRecords"] == rb["totalRecords"] and set(rb["folders"]) == {"package", "records"}:
        context.finish("VERIFIED")
    elif any(x["state"] in {"DISPATCHED", "UNCERTAIN"} for x in context.state["actions"].values()):
        context.finish("UPLOAD_UNCERTAIN", "ORIGINAL_DISPATCH_OR_RESPONSE_UNRESOLVED")
    elif status in ACTIVE or not context.state["transfer"]["submitted"]:
        context.finish("INGESTING", "SOURCE_READBACK_PENDING")
    else:
        context.finish("VERIFYING", "SOURCE_READBACK_INCOMPLETE")


def _run(package_workspace, identifier, *, cancelled=None, observe_only=False, evidence=None):
    root = Path(package_workspace).absolute()
    directory, _ = _planned(root, identifier)
    with _operation_lock(directory):
        context = Context(root, identifier, cancelled)
        try:
            _cancelled(cancelled)
            if _future(context.state.get("retryAt")):
                return context.summary()
            context.state["retryAt"] = None
            if evidence is not None:
                _reconcile(context, evidence)
            if not observe_only and evidence is None and context.state["state"] != "VERIFIED":
                try:
                    _upload(context)
                except Stop as exc:
                    if exc.state != "UPLOAD_UNCERTAIN":
                        raise
                    context.finish(exc.state, exc.code, exc.retry_at)
                    # An observed original SourceID+metadata+file can still resolve
                    # content receiving without repeating this uncertain upload.
            _observe(context)
        except Stop as exc:
            _readback_counts(context)
            context.finish(exc.state, exc.code, exc.retry_at)
        except Unresolved as exc:
            _readback_counts(context)
            context.state["lastObservationDetails"] = clone(exc.details)
            context.finish("NEEDS_REVIEW", exc.code)
        return context.summary()


def run(package_workspace, operation_id, *, cancelled=None):
    return _run(package_workspace, operation_id, cancelled=cancelled)


def refresh(package_workspace, operation_id, *, cancelled=None):
    return _run(package_workspace, operation_id, cancelled=cancelled, observe_only=True)


def reconciliation_template(kind="original-response"):
    if kind == "original-response":
        return {"schema": EVIDENCE_SCHEMA, "kind": kind, "operationId": "original-operation-id",
                "action": "complete", "requestSha256": "EXACT_ORIGINAL_REQUEST_SHA256",
                "status": 200, "headers": {"etag": "ORIGINAL_ETAG",
                    "preservica-progress-token": "ORIGINAL_PROGRESS_TOKEN"},
                "bodyBase64": "BASE64_OF_THE_ORIGINAL_COMPLETE_XML_BODY",
                "observedAt": "2026-10-12T00:00:00Z",
                "sourceDescription": "Original retained HTTP response for this exact upload"}
    if kind == "progress-observation":
        return {"schema": EVIDENCE_SCHEMA, "kind": kind, "operationId": "original-operation-id",
                "action": "complete", "requestSha256": "EXACT_ORIGINAL_REQUEST_SHA256",
                "bucket": "tenant.package.upload", "key": "EXACT_ORIGINAL_OBJECT_KEY",
                "progressToken": "ORIGINAL_PROGRESS_TOKEN",
                "sourceDescription": "Original upload response retained outside this client"}
    if kind == "process-observation":
        return {"schema": EVIDENCE_SCHEMA, "kind": kind, "operationId": "original-operation-id",
                "processId": "ORIGINAL_MONITOR_MAPPED_ID",
                "sourceDescription": "Explicit original process selection; not inferred from a title or time"}
    raise Error("Unsupported reconciliation evidence kind")


def _validate_evidence(context, value):
    require(isinstance(value, dict), "Reconciliation evidence must be a JSON object")
    kind = value.get("kind")
    template = reconciliation_template(kind)
    require(set(value) == set(template), "Reconciliation evidence fields do not match the selected kind")
    require(value.get("schema") == EVIDENCE_SCHEMA and value.get("operationId") == context.planned["operationId"],
            "Evidence belongs to a different original operation")
    source = value.get("sourceDescription")
    require(isinstance(source, str) and 1 <= len(source) <= 4000, "Describe the retained original evidence source")
    if kind in {"original-response", "progress-observation"}:
        action = value.get("action")
        require(action in {"init", "single", "complete"}, "Reconcile only an original upload action")
        original = context.state["actions"].get(action)
        require(isinstance(original, dict), "No original dispatch exists for this action")
        request = _load(context.directory, original["request"] + "/request.json")
        require(value.get("requestSha256") == digest(request) == original.get("requestSha256")
                and request.get("action") == action, "Evidence does not bind the exact original HTTP request")
    else:
        process_id = value.get("processId")
        require(isinstance(process_id, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,239}", process_id),
                "Select the original observed process ID")
    return clone(value)


def _adopted_response(context, descriptor):
    raw = p.read_regular(context.directory, descriptor["path"], MAX_STATE)
    require(len(raw) == descriptor["bytes"] and p.digest(raw) == descriptor["sha256"],
            "Original adopted evidence changed")
    value = p.parse_json(raw)
    require(value.get("kind") == "original-response" and value.get("operationId") == context.planned["operationId"],
            "Adopted response belongs to another operation")
    action = context.state["actions"].get(value.get("action"))
    require(action and action.get("requestSha256") == value.get("requestSha256"),
            "Adopted response lost its original request binding")
    try:
        body = base64.b64decode(value["bodyBase64"], validate=True)
    except (ValueError, TypeError):
        raise Error("Invalid retained original response encoding")
    return {"receipt": {"status": value["status"], "body": {"complete": True},
                       "error": None, "completedAt": value["observedAt"]},
            "headers": {k.lower(): v for k, v in value["headers"].items()}, "raw": body}


def _reconcile(context, evidence):
    value = _validate_evidence(context, evidence)
    kind = value["kind"]
    if kind == "original-response":
        require(isinstance(value["status"], int) and not isinstance(value["status"], bool), "Invalid original status")
        headers = value["headers"]
        require(isinstance(headers, dict) and all(isinstance(k, str) and isinstance(v, str)
                for k, v in headers.items()), "Original response headers must be strings")
        require(not (set(k.lower() for k in headers) & SECRET_HEADERS), "Do not include credentials or cookies in evidence")
        try:
            raw = base64.b64decode(value["bodyBase64"], validate=True)
        except (ValueError, TypeError):
            raise Error("Original response body must be valid base64")
        require(len(raw) <= context.config["maxResponseBytes"], "Original response evidence is too large")
        try:
            at = dt.datetime.fromisoformat(value["observedAt"].replace("Z", "+00:00"))
            require(at.tzinfo is not None, "Original observation needs a timezone")
        except (ValueError, TypeError, AttributeError):
            raise Error("Invalid original response observation timestamp")
        response = {"receipt": {"status": value["status"], "body": {"complete": True},
                    "error": None, "completedAt": value["observedAt"]},
                    "headers": {k.lower(): v for k, v in headers.items()}, "raw": raw}
        action = value["action"]
        parser = {"init": _parse_init, "single": _parse_single, "complete": _parse_complete}[action]
        result = parser(context, response)
        original = context.state["actions"][action]
        if original["state"] == "CONFIRMED":
            require(original["result"] == result, "An existing confirmed original result cannot be replaced")
        safe, changed = _safe_body(raw, context.origin, os.environ.get(context.config["accessTokenEnv"]))
        retained = {**value, "headers": _safe_headers(list(headers.items()), context.origin),
                    "bodyBase64": base64.b64encode(safe).decode("ascii"),
                    "sourceBody": {"bytes": len(raw), "sha256": p.digest(raw), "redacted": changed}}
        descriptor = context.evidence("original-response", retained)
        original.update({"state": "CONFIRMED", "result": result, "adoption": descriptor})
        if action == "init":
            prior = context.state["transfer"]["uploadId"]
            require(prior in {None, result["uploadId"]}, "Original multipart upload ID differs")
            context.state["transfer"]["uploadId"] = result["uploadId"]
        else:
            context.state["transfer"]["submitted"] = True
            context.state["transfer"]["completion"] = result
            if result.get("progressToken"):
                context.state["transfer"]["progressToken"] = result["progressToken"]
        context.note("ORIGINAL_RESPONSE_ADOPTED", action=action, requestSha256=value["requestSha256"],
                     evidence=descriptor)
    elif kind == "progress-observation":
        require(value["action"] in {"single", "complete"}, "A progress token follows an upload completion")
        require(value["bucket"] == context.planned["bucket"] and value["key"] == context.planned["key"],
                "Progress observation belongs to a different original target")
        token = value["progressToken"]
        require(isinstance(token, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,239}", token),
                "Invalid original progress token")
        prior = context.state["transfer"]["progressToken"]
        require(prior in {None, token}, "An original progress token is already selected")
        descriptor = context.evidence("original-progress-observation", value)
        context.state["transfer"]["progressToken"] = token
        context.state["transfer"]["progressObservation"] = {"kind": "EXPLICIT_ORIGINAL_RESPONSE",
            "evidence": descriptor, "scope": "Operator-provided original response association; repository source readback remains required."}
        context.note("ORIGINAL_PROGRESS_OBSERVATION_SELECTED", evidence=descriptor)
    else:
        descriptor = context.evidence("original-process-selection", value)
        context.state["ingest"]["processId"] = value["processId"]
        context.state["ingest"].setdefault("processSelections", []).append(descriptor)
        context.state["ingest"]["processStatus"] = None
        context.note("ORIGINAL_PROCESS_OBSERVATION_SELECTED", evidence=descriptor)
    context.state["lastIssue"] = None
    context.publish()


def reconcile(package_workspace, operation_id, evidence, *, cancelled=None):
    # Exact caller value is cloned before any provider or journal action.
    return _run(package_workspace, operation_id, cancelled=cancelled,
                observe_only=True, evidence=clone(evidence))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("configuration-template")
    evidence = sub.add_parser("reconciliation-template")
    evidence.add_argument("--kind", choices=["original-response", "progress-observation", "process-observation"],
                          default="original-response")
    command = sub.add_parser("plan")
    command.add_argument("--workspace", required=True)
    command.add_argument("--configuration", required=True)
    command.add_argument("--operation-id", required=True)
    for name in ("show", "run", "refresh", "reconcile"):
        command = sub.add_parser(name)
        command.add_argument("--workspace", required=True)
        command.add_argument("--operation-id", required=name != "show")
        if name == "reconcile":
            command.add_argument("--evidence", required=True)
    args = parser.parse_args(argv)
    if args.command == "configuration-template":
        result = configuration_template()
    elif args.command == "reconciliation-template":
        result = reconciliation_template(args.kind)
    elif args.command == "plan":
        path = Path(args.configuration).absolute()
        result = plan(args.workspace, _load(path.parent, path.name), args.operation_id)
    elif args.command == "show":
        result = show(args.workspace, args.operation_id)
    elif args.command == "reconcile":
        path = Path(args.evidence).absolute()
        result = reconcile(args.workspace, args.operation_id, _load(path.parent, path.name))
    else:
        result = globals()[args.command](args.workspace, args.operation_id)
    print(json.dumps(result, ensure_ascii=False, indent=2, allow_nan=False))
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (Error, q.Error, p.PreservationError, OSError, KeyError, ValueError) as exc:
        print(json.dumps({"ok": False, "error": type(exc).__name__,
                          "message": str(exc) if isinstance(exc, (Error, q.Error, p.PreservationError)) else
                                     "The original operation remains retained; inspect its saved journal."}), file=sys.stderr)
        raise SystemExit(1)

#!/usr/bin/env python3
"""RODA v2 staging and ingest client for an immutable research-transfer workspace.

Uses Python's standard library. The repository source contract is pinned in
RODA_REST.md. Every mutating HTTP request has a durable local dispatch marker;
a lost response is reconciled against the original resource/job.
"""
from __future__ import annotations

import argparse
import base64
import contextlib
import datetime as dt
import fcntl
import hashlib
import http.client
import json
import os
from pathlib import Path, PurePosixPath
import re
import ssl
import stat
import sys
import tempfile
import time
import urllib.parse
import zipfile

SCHEMA = "stellar-forge.roda-client.v1"
HANDOFF_SCHEMA = "stellar-forge.roda-research-transfer.v1"
SOURCE_COMMIT = "668f61b2d7d3154cb6cc3220ff83cbbd7e206822"
TRANSFER_CLASS = "org.roda.core.data.v2.ip.TransferredResource"
AIP_CLASS = "org.roda.core.data.v2.ip.AIP"
BAGIT_PLUGIN = "org.roda.core.plugins.base.ingest.BagitToAIPPlugin"
INGEST_PLUGINS = {
    "org.roda.core.plugins.base.ingest.v2.ConfigurableIngestPlugin",
    "org.roda.core.plugins.base.ingest.v2.MinimalIngestPlugin",
}
# DefaultIngestPlugin mutates the submitted Job map during service validation.
# Worker-only job/lock/parent parameters are added to a copied map (JobsHelper).
DERIVED_JOB_PARAMETERS = {
    "parameter.total_steps", "parameter.create_submission", "parameter.reporting_class",
}
TERMINAL = {"COMPLETED", "FAILED_DURING_CREATION", "FAILED_TO_COMPLETE", "STOPPED", "REJECTED"}
PAUSED = {"PENDING_APPROVAL", "SCHEDULED"}
KNOWN_STATES = TERMINAL | PAUSED | {"CREATED", "STARTED", "STOPPING", "TO_BE_CLEANED"}
SAFE_HEADERS = {
    "content-type", "content-length", "content-disposition", "date", "etag",
    "last-modified", "retry-after", "location", "x-request-id", "x-correlation-id",
}
CHUNK = 256 * 1024
JSON_LIMIT = 16 * 1024 * 1024
HEX = re.compile(r"[0-9a-f]{64}\Z")
ENV = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
SIMPLE_ID = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,511}\Z")


class RodaError(Exception):
    def __init__(self, code, message, **details):
        super().__init__(message)
        self.code, self.details = code, details

    def result(self):
        return {"schema": SCHEMA, "error": self.code, "message": str(self), **self.details}


def _fail(code, message, **details):
    raise RodaError(code, message, **details)


def _now():
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def _json(value):
    return (json.dumps(value, ensure_ascii=False, allow_nan=False, sort_keys=True,
                       separators=(",", ":")) + "\n").encode("utf-8")


def _sha(body):
    return hashlib.sha256(body).hexdigest()


def _object_pairs(pairs):
    out = {}
    for key, value in pairs:
        if key in out:
            _fail("DUPLICATE_JSON_KEY", "A JSON object contains a duplicate key.", key=key)
        out[key] = value
    return out


def _parse(body):
    try:
        return json.loads(body.decode("utf-8"), object_pairs_hook=_object_pairs,
                          parse_constant=lambda _: _fail("INVALID_JSON", "Non-finite JSON number."))
    except (UnicodeError, ValueError, RecursionError) as exc:
        _fail("INVALID_JSON", "Expected a complete UTF-8 JSON document.", cause=type(exc).__name__)


def _private_directory(path):
    path = Path(path)
    path.mkdir(mode=0o700, parents=True, exist_ok=True)
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or path.resolve() != path.absolute():
        _fail("UNSAFE_DIRECTORY", "Journal directories must be real local directories.", path=str(path))
    return path


def _fsync_directory(path):
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _read(path, limit=JSON_LIMIT):
    path = Path(path)
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode) or before.st_size > limit:
            _fail("INVALID_LOCAL_FILE", "Expected a bounded regular file.", path=str(path), limit=limit)
        chunks, size = [], 0
        while True:
            block = os.read(fd, min(CHUNK, limit + 1 - size))
            if not block:
                break
            chunks.append(block)
            size += len(block)
            if size > limit:
                _fail("LOCAL_FILE_TOO_LARGE", "Local file exceeded its declared limit.", path=str(path))
        after = os.fstat(fd)
        if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (
                after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns):
            _fail("LOCAL_FILE_CHANGED", "Local file changed while it was read.", path=str(path))
        return b"".join(chunks)
    finally:
        os.close(fd)


def _read_json(path, limit=JSON_LIMIT):
    return _parse(_read(path, limit))


def _optional_json(path):
    try:
        return _read_json(path)
    except FileNotFoundError:
        return None


def _write(path, body, *, replace=False):
    """Publish complete bytes; exclusive publication never exposes a partial target."""
    path = Path(path)
    _private_directory(path.parent)
    fd, tmp = tempfile.mkstemp(prefix=".write-", dir=path.parent)
    try:
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "wb", buffering=0) as stream:
            pending = memoryview(body)
            while pending:
                written = stream.write(pending)
                if not written:
                    raise OSError("Atomic file write made no progress")
                pending = pending[written:]
            stream.flush()
            os.fsync(stream.fileno())
        if replace:
            os.replace(tmp, path)
        else:
            try:
                os.link(tmp, path, follow_symlinks=False)
            except FileExistsError:
                if _read(path, max(len(body), 1)) != body:
                    _fail("IMMUTABLE_RECORD_CONFLICT", "A saved immutable record has different bytes.", path=str(path))
        _fsync_directory(path.parent)
    finally:
        try:
            os.unlink(tmp)
        except FileNotFoundError:
            pass


def _write_json(path, value, *, replace=False):
    _write(path, _json(value), replace=replace)


def _hash_file(path, *, expected=None):
    path = Path(path)
    fd = os.open(path, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode):
            _fail("INVALID_TRANSFER_FILE", "The transfer must be a regular file.")
        digest, total = hashlib.sha256(), 0
        while True:
            block = os.read(fd, CHUNK)
            if not block:
                break
            digest.update(block)
            total += len(block)
        after = os.fstat(fd)
        if (before.st_dev, before.st_ino, before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (
                after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns):
            _fail("TRANSFER_CHANGED", "Transfer bytes changed while being hashed.")
        actual = {"bytes": total, "sha256": digest.hexdigest()}
        if expected and (actual["bytes"] != expected["bytes"] or actual["sha256"] != expected["sha256"]):
            _fail("TRANSFER_HASH_MISMATCH", "Transfer bytes differ from the immutable handoff.", actual=actual)
        return actual
    finally:
        os.close(fd)


def _relative(root, name):
    if not isinstance(name, str) or not name or "\\" in name:
        _fail("INVALID_RELATIVE_PATH", "Expected a nonempty relative POSIX path.")
    posix = PurePosixPath(name)
    if posix.is_absolute() or any(p in {"", ".", ".."} for p in name.split("/")):
        _fail("INVALID_RELATIVE_PATH", "Prepared paths must remain within the workspace.", path=name)
    path = root.joinpath(*posix.parts)
    if path.resolve() != path.absolute() or not path.is_relative_to(root):
        _fail("INVALID_RELATIVE_PATH", "Prepared files cannot traverse symbolic links.", path=name)
    return path


def _string(value, field, limit=1024):
    if not isinstance(value, str) or not value.strip() or len(value) > limit or any(ord(c) < 32 for c in value):
        _fail("INVALID_FIELD", "Expected a nonempty bounded string without control characters.", field=field)
    return value


def _id(value, field):
    if not isinstance(value, str) or not SIMPLE_ID.fullmatch(value):
        _fail("INVALID_IDENTIFIER", "Invalid service identifier.", field=field)
    return value


def _integer(value, field, low, high):
    if isinstance(value, bool) or not isinstance(value, int) or not low <= value <= high:
        _fail("INVALID_FIELD", "Integer is outside the accepted range.", field=field, minimum=low, maximum=high)
    return value


def _base_url(value):
    _string(value, "baseUrl", 4096)
    url = urllib.parse.urlsplit(value)
    if (url.scheme not in {"https", "http"} or not url.hostname or url.username is not None
            or url.password is not None or url.query or url.fragment or "%" in url.netloc):
        _fail("INVALID_BASE_URL", "Use an absolute repository HTTP(S) URL without credentials, query or fragment.")
    try:
        _ = url.port
    except ValueError:
        _fail("INVALID_BASE_URL", "Repository port is invalid.")
    path = url.path.rstrip("/")
    if any(p in {".", ".."} for p in path.split("/")) or path.endswith("/api/v2"):
        _fail("INVALID_BASE_URL", "baseUrl is the application root, before /api/v2.")
    return urllib.parse.urlunsplit((url.scheme, url.netloc, path, "", ""))


def read_handoff(workspace):
    root = Path(workspace).resolve(strict=True)
    from roda import Error as PreparationError, verify_workspace
    try:
        verified_handoff = verify_workspace(root)
    except (PreparationError, zipfile.BadZipFile, UnicodeError, ValueError, KeyError, TypeError) as exc:
        _fail("PREPARED_WORKSPACE_INVALID", "The original producer rejected the prepared workspace.",
              cause=type(exc).__name__, reason=str(exc)[:2048])
    raw = _read(root / "handoff.json")
    handoff = _parse(raw)
    if handoff != verified_handoff:
        _fail("HANDOFF_CHANGED", "Prepared handoff changed after the original producer verification.")
    if not isinstance(handoff, dict) or handoff.get("schema") != HANDOFF_SCHEMA:
        _fail("INVALID_HANDOFF", "Expected the original prepared RODA research-transfer handoff.")
    if handoff.get("packageModel") != "one-bag-one-aip":
        _fail("INVALID_PACKAGE_MODEL", "This client receives one original bag as one AIP.")
    transfer = handoff.get("transfer")
    agreement = handoff.get("agreement")
    repository = handoff.get("repository")
    if not all(isinstance(v, dict) for v in (transfer, agreement, repository)):
        _fail("INVALID_HANDOFF", "Transfer, agreement and repository descriptors are required.")
    if transfer.get("path") != "transfer.zip" or not HEX.fullmatch(str(transfer.get("sha256", ""))):
        _fail("INVALID_HANDOFF", "The handoff must bind transfer.zip with SHA-256.")
    _integer(transfer.get("bytes"), "transfer.bytes", 1, 2**63 - 1)
    _string(transfer.get("bagId"), "transfer.bagId")
    _string(repository.get("name"), "repository.name")
    _base_url(repository.get("baseUrl"))
    if not isinstance(handoff.get("verification"), dict) or not handoff["verification"]:
        _fail("INVALID_HANDOFF", "The original full preservation verification must be retained.")
    if not HEX.fullmatch(str(agreement.get("sha256", ""))):
        _fail("INVALID_HANDOFF", "The agreement SHA-256 is required.")
    transfer_path = _relative(root, transfer["path"])
    _hash_file(transfer_path, expected=transfer)
    agreement_raw = _read(_relative(root, agreement.get("path")))
    if _sha(agreement_raw) != agreement["sha256"]:
        _fail("AGREEMENT_HASH_MISMATCH", "The prepared agreement differs from its handoff.")
    _parse(agreement_raw)
    return {"root": root, "handoff": handoff, "handoffSha256": _sha(raw),
            "transferPath": transfer_path, "agreementBytes": agreement_raw}


def _config(path):
    raw = _read(Path(path).resolve(strict=True), 1024 * 1024)
    value = _parse(raw)
    if not isinstance(value, dict) or value.get("schema") != SCHEMA:
        _fail("INVALID_CONFIG", "Expected a RODA client configuration.")
    allowed = {"schema", "baseUrl", "repositoryUsername", "auth", "stagingParentUuid",
               "caFile", "timeoutSeconds", "maxResponseBytes", "reportPageSize", "maxPages", "allowHttp"}
    if set(value) - allowed:
        _fail("UNKNOWN_CONFIG_FIELD", "Configuration contains unknown fields.", fields=sorted(set(value) - allowed))
    out = {"schema": SCHEMA, "baseUrl": _base_url(value.get("baseUrl")),
           "repositoryUsername": _string(value.get("repositoryUsername"), "repositoryUsername", 255),
           "timeoutSeconds": _integer(value.get("timeoutSeconds", 120), "timeoutSeconds", 1, 3600),
           "maxResponseBytes": _integer(value.get("maxResponseBytes", JSON_LIMIT), "maxResponseBytes", 1024, 64 * 1024 * 1024),
           "reportPageSize": _integer(value.get("reportPageSize", 100), "reportPageSize", 1, 1000),
           "maxPages": _integer(value.get("maxPages", 1000), "maxPages", 1, 10000),
           "allowHttp": value.get("allowHttp", False)}
    if not isinstance(out["allowHttp"], bool):
        _fail("INVALID_CONFIG", "allowHttp must be a boolean.")
    if out["baseUrl"].startswith("http:") and not out["allowHttp"]:
        _fail("HTTP_NOT_SELECTED", "HTTP repositories require explicit allowHttp in the selected configuration.")
    auth = value.get("auth")
    if not isinstance(auth, dict):
        _fail("INVALID_CONFIG", "Choose HTTP basic or bearer authentication using environment references.")
    key = "tokenEnv" if auth.get("type") == "bearer" else "passwordEnv" if auth.get("type") == "basic" else None
    if key is None or set(auth) != {"type", key} or not isinstance(auth.get(key), str) or not ENV.fullmatch(auth[key]):
        _fail("INVALID_CONFIG", "Authentication must contain its type and one environment variable name.")
    out["auth"] = dict(auth)
    if value.get("stagingParentUuid") is not None:
        out["stagingParentUuid"] = _id(value["stagingParentUuid"], "stagingParentUuid")
    if value.get("caFile") is not None:
        ca = Path(value["caFile"]).expanduser().resolve(strict=True)
        out["caFile"] = str(ca)
        out["caSha256"] = _hash_file(ca)["sha256"]
    return out


def _template(path, handoff):
    raw = _read(Path(path).resolve(strict=True), 1024 * 1024)
    value = _parse(raw)
    required = {"name", "plugin", "pluginParameters", "priority", "parallelism"}
    if not isinstance(value, dict) or set(value) != required:
        _fail("INVALID_JOB_TEMPLATE", "Template must contain name, plugin, pluginParameters, priority and parallelism.")
    _string(value["name"], "job.name", 160)
    if value["plugin"] not in INGEST_PLUGINS:
        _fail("INVALID_INGEST_PLUGIN", "Select one of the reviewed RODA v2 ingest workflows.")
    parameters = value["pluginParameters"]
    if not isinstance(parameters, dict) or not all(isinstance(k, str) and isinstance(v, str) for k, v in parameters.items()):
        _fail("INVALID_JOB_TEMPLATE", "pluginParameters must be an exact string-to-string map.")
    if {"parameter.total_steps", "parameter.reporting_class"} & set(parameters):
        _fail("DERIVED_JOB_PARAMETER", "Leave total_steps and reporting_class to the original ingest implementation.")
    if ("parameter.create_submission" in parameters
            and parameters["parameter.create_submission"] not in {"true", "false"}):
        _fail("INVALID_JOB_TEMPLATE", "Explicit create_submission must be the original lowercase boolean string.")
    if parameters.get("parameter.sip_to_aip_class") != BAGIT_PLUGIN:
        _fail("WRONG_SIP_PARSER", "The reviewed transfer requires the original BagIt-to-AIP parser.")
    if value["priority"] not in {"URGENT", "HIGH", "MEDIUM", "LOW"} or value["parallelism"] not in {"LIMITED", "NORMAL"}:
        _fail("INVALID_JOB_TEMPLATE", "Invalid RODA priority or parallelism.")
    parent = handoff.get("collection", {}).get("parentAipId")
    selected = parameters.get("parameter.parent_id", "")
    if parent:
        if selected != parent or parameters.get("parameter.force_parent_id") != "true":
            _fail("COLLECTION_SCOPE_MISMATCH", "Template must force the exact parent AIP in the submission agreement.")
    elif selected:
        _fail("COLLECTION_SCOPE_MISMATCH", "Template parent must match the prepared agreement's collection scope.")
    return value, _sha(raw)


def _root_lock(root):
    @contextlib.contextmanager
    def acquire():
        path = root / "workspace.lock"
        fd = os.open(path, os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_uid != os.getuid():
                _fail("INVALID_WORKSPACE_LOCK", "Expected the original owned workspace lock.")
            try:
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError:
                _fail("WORKSPACE_BUSY", "The original workspace is in use by another operation.")
            yield
        finally:
            os.close(fd)
    return acquire()


def _error_class(status):
    if status == 401:
        return "AUTHENTICATION_FAILED"
    if status == 403:
        return "PERMISSION_DENIED"
    if status == 429:
        return "RATE_LIMITED"
    if status == 409:
        return "REMOTE_CONFLICT"
    if status == 404:
        return "REMOTE_NOT_FOUND"
    if 300 <= status < 400:
        return "REDIRECT_NOT_ACCEPTED"
    return "PROVIDER_REJECTED" if status < 500 else "PROVIDER_ERROR"


class _Client:
    """Caller holds the one original workspace.lock for this complete scope."""
    def __init__(self, workspace, config_file=None):
        self.inputs = read_handoff(workspace)
        self.root = self.inputs["root"]
        self.remote = self.root / "remote"
        self.config = _config(config_file) if config_file else None
        self.plan = _optional_json(self.remote / "plan.json")
        self.actor = None
        if self.plan is not None:
            self._validate_plan()

    def _validate_plan(self):
        plan = self.plan
        if (plan.get("schema") != "stellar-forge.roda-ingest-plan.v1"
                or plan.get("handoffSha256") != self.inputs["handoffSha256"]
                or plan.get("transfer") != self.inputs["handoff"]["transfer"]
                or plan.get("agreement") != self.inputs["handoff"]["agreement"]):
            _fail("PLAN_SOURCE_MISMATCH", "The saved remote operation is bound to a different prepared handoff.")
        if self.config is not None and self.config != plan.get("config"):
            _fail("CONFIGURATION_CHANGED", "Resume with the originally selected repository/account/configuration.")
        identity = {k: plan[k] for k in ("handoffSha256", "transfer", "agreement", "config", "jobTemplate")}
        if _sha(_json(identity)) != plan.get("operationId"):
            _fail("PLAN_IDENTITY_MISMATCH", "The original ingest-plan fingerprint is invalid.")
        if (plan.get("uploadName") != "sf88-" + plan["operationId"] + ".zip"
                or plan.get("jobName") != plan["jobTemplate"]["name"] + " [sf88:" + plan["operationId"] + "]"):
            _fail("PLAN_NAME_MISMATCH", "Saved remote names differ from the original operation identity.")

    def prepare(self, job_template_file=None):
        if self.config is None:
            _fail("CONFIG_REQUIRED", "A selected repository configuration is required.")
        if self.plan:
            if job_template_file:
                template, _ = _template(job_template_file, self.inputs["handoff"])
                if template != self.plan["jobTemplate"]:
                    _fail("JOB_TEMPLATE_CHANGED", "Resume with the exact original job template.")
            return self.local_status()
        if not job_template_file:
            _fail("JOB_TEMPLATE_REQUIRED", "Select the reviewed repository ingest job template.")
        if self.config["baseUrl"] != _base_url(self.inputs["handoff"]["repository"]["baseUrl"]):
            _fail("REPOSITORY_MISMATCH", "Configured repository differs from the submission agreement.")
        template, template_sha = _template(job_template_file, self.inputs["handoff"])
        identity = {"handoffSha256": self.inputs["handoffSha256"],
                    "transfer": self.inputs["handoff"]["transfer"],
                    "agreement": self.inputs["handoff"]["agreement"],
                    "config": self.config, "jobTemplate": template}
        operation_id = _sha(_json(identity))
        self.plan = {"schema": "stellar-forge.roda-ingest-plan.v1", **identity,
                     "operationId": operation_id, "preparedAt": _now(),
                     "jobTemplateSourceSha256": template_sha, "sourceCommit": SOURCE_COMMIT,
                     "uploadName": "sf88-" + operation_id + ".zip",
                     "jobName": template["name"] + " [sf88:" + operation_id + "]"}
        _private_directory(self.remote)
        _write_json(self.remote / "plan.json", self.plan)
        self._validate_plan()
        return self.local_status()

    def _require_plan(self):
        if not self.plan or not self.config:
            _fail("PLAN_REQUIRED", "Prepare the original handoff with its repository configuration and job template.")

    def _auth_header(self):
        auth = self.config["auth"]
        name = auth.get("tokenEnv", auth.get("passwordEnv"))
        secret = os.environ.get(name)
        if not secret or any(c in secret for c in "\r\n\x00"):
            _fail("CREDENTIAL_UNAVAILABLE", "The selected credential environment variable is unavailable.", variable=name)
        if auth["type"] == "bearer":
            return "Bearer " + secret
        user = self.config["repositoryUsername"]
        if ":" in user:
            _fail("INVALID_BASIC_USERNAME", "HTTP basic usernames cannot contain a colon.")
        return "Basic " + base64.b64encode((user + ":" + secret).encode("utf-8")).decode("ascii")

    def _exchange_dir(self, kind):
        base = _private_directory(self.remote / "exchanges")
        for number in range(1, 1000000):
            path = base / ("%06d-%s" % (number, kind))
            try:
                path.mkdir(mode=0o700)
                return path
            except FileExistsError:
                continue
        _fail("JOURNAL_LIMIT", "The response journal reached its supported entry count.")

    def _completed(self, directory):
        record = _optional_json(directory / "response.json")
        if record is None:
            return None
        request = _read(directory / "request.json")
        request_value = _parse(request)
        if (record.get("requestSha256") != _sha(request)
                or request_value.get("operationId") != self.plan["operationId"]):
            _fail("SAVED_RESPONSE_REQUEST_CHANGED", "Saved response no longer binds its original request.")
        if record.get("bodyReference") == "transfer.zip":
            actual = _hash_file(self.inputs["transferPath"], expected=self.plan["transfer"])
            if actual != {"sha256": record["bodySha256"], "bytes": record["bodyBytes"]}:
                _fail("SAVED_RESPONSE_CHANGED", "The retained staged-byte reference has changed.")
            return record, None
        body = _read(directory / "response.body", self.config["maxResponseBytes"])
        if _sha(body) != record.get("bodySha256") or len(body) != record.get("bodyBytes"):
            _fail("SAVED_RESPONSE_CHANGED", "A retained HTTP response has changed.", directory=str(directory))
        return record, body

    def _request(self, method, endpoint, *, body=None, multipart=False, mutation=False,
                 stage=None, expected=(200,), verify_transfer=False):
        self._require_plan()
        directory = _private_directory(self.remote / stage) if stage else self._exchange_dir("read")
        url = self.config["baseUrl"] + "/api/v2" + endpoint
        if not endpoint.startswith("/") or "#" in endpoint:
            _fail("INVALID_API_PATH", "Expected an original relative RODA API path.")
        boundary = "sf88-" + self.plan["operationId"]
        prefix, suffix = b"", b""
        if multipart:
            prefix = ('--' + boundary + '\r\nContent-Disposition: form-data; name="resource"; filename="' +
                      self.plan["uploadName"] + '"\r\nContent-Type: application/zip\r\n\r\n').encode("ascii")
            suffix = ("\r\n--" + boundary + "--\r\n").encode("ascii")
            length = len(prefix) + self.plan["transfer"]["bytes"] + len(suffix)
            content_type = "multipart/form-data; boundary=" + boundary
            descriptor = {"kind": "multipart/resource", "file": self.plan["transfer"],
                          "filename": self.plan["uploadName"], "prefixSha256": _sha(prefix),
                          "suffixSha256": _sha(suffix), "bytes": length}
        else:
            body = b"" if body is None else body
            length, content_type = len(body), "application/json"
            descriptor = {"kind": "bytes", "bytes": length, "sha256": _sha(body)}
        request = {"schema": "stellar-forge.roda-http-request.v1", "method": method, "url": url,
                   "mutation": mutation, "body": descriptor, "operationId": self.plan["operationId"],
                   "repositoryUsername": self.config["repositoryUsername"],
                   "authReference": self.config["auth"]}
        _write_json(directory / "request.json", request)
        if not multipart:
            _write(directory / "request.body", body)
        complete = self._completed(directory)
        if complete is not None:
            record, received = complete
            if record["status"] not in expected:
                _fail(_error_class(record["status"]), "The original repository request returned an error.",
                      status=record["status"], response=str(directory.relative_to(self.root)),
                      retryAfter=record["headers"].get("retry-after"))
            return record, received
        if mutation and (directory / "dispatch.json").exists():
            _fail("REMOTE_WRITE_UNCERTAIN", "Reconcile the original dispatched request before any further mutation.",
                  stage=stage, operationId=self.plan["operationId"])
        authorization = self._auth_header()
        target = urllib.parse.urlsplit(url)
        context = None
        if target.scheme == "https":
            if self.config.get("caFile"):
                if _hash_file(self.config["caFile"])["sha256"] != self.config["caSha256"]:
                    _fail("CA_SOURCE_CHANGED", "The selected repository CA file has changed.")
            context = ssl.create_default_context(cafile=self.config.get("caFile"))
        connection = (http.client.HTTPSConnection(target.hostname, target.port, timeout=self.config["timeoutSeconds"], context=context)
                      if context else http.client.HTTPConnection(target.hostname, target.port, timeout=self.config["timeoutSeconds"]))
        deadline = time.monotonic() + self.config["timeoutSeconds"]
        phase = "CONNECT"
        def remaining():
            value = deadline - time.monotonic()
            if value <= 0:
                raise TimeoutError("RODA request deadline elapsed")
            if connection.sock is not None:
                connection.sock.settimeout(value)
        try:
            connection.connect()
            remaining()
            phase = "DISPATCH"
            _write_json(directory / "dispatch.json", {"requestSha256": _sha(_json(request)),
                        "dispatchedAt": _now(), "mutation": mutation})
            path = urllib.parse.urlunsplit(("", "", target.path, target.query, ""))
            connection.putrequest(method, path, skip_accept_encoding=True)
            connection.putheader("Authorization", authorization)
            connection.putheader("Accept", "application/octet-stream" if verify_transfer else "application/json")
            connection.putheader("Accept-Encoding", "identity")
            if method != "GET":
                connection.putheader("Content-Type", content_type)
                connection.putheader("Content-Length", str(length))
            connection.endheaders()
            if multipart:
                connection.send(prefix)
                fd = os.open(self.inputs["transferPath"], os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
                try:
                    digest, count = hashlib.sha256(), 0
                    while True:
                        remaining()
                        chunk = os.read(fd, CHUNK)
                        if not chunk:
                            break
                        count += len(chunk)
                        digest.update(chunk)
                        connection.send(chunk)
                    if count != self.plan["transfer"]["bytes"] or digest.hexdigest() != self.plan["transfer"]["sha256"]:
                        _fail("TRANSFER_CHANGED_DURING_UPLOAD", "Uploaded source no longer matches the prepared transfer.")
                finally:
                    os.close(fd)
                remaining()
                connection.send(suffix)
            elif body:
                for offset in range(0, len(body), CHUNK):
                    remaining()
                    connection.send(body[offset:offset + CHUNK])
            remaining()
            phase = "RESPONSE"
            response = connection.getresponse()
            headers = {k.lower(): v for k, v in response.getheaders() if k.lower() in SAFE_HEADERS}
            response_head = {"schema": "stellar-forge.roda-http-response.v1", "status": response.status,
                             "headers": headers, "receivedAt": _now(), "requestSha256": _sha(_json(request))}
            _write_json(directory / "response-head.json", response_head)
            limit = self.plan["transfer"]["bytes"] if verify_transfer and response.status == 200 else self.config["maxResponseBytes"]
            chunks, digest, count = [], hashlib.sha256(), 0
            while True:
                remaining()
                block = response.read(min(CHUNK, limit + 1 - count))
                if not block:
                    break
                count += len(block)
                digest.update(block)
                if count > limit:
                    _fail("RESPONSE_TOO_LARGE", "Repository response exceeded its selected receiving limit.", limit=limit)
                if not (verify_transfer and response.status == 200):
                    chunks.append(block)
            declared = headers.get("content-length")
            if declared is not None and (not declared.isdigit() or int(declared) != count):
                _fail("HTTP_BODY_INCOMPLETE", "Repository response length does not match Content-Length.")
            record = {**response_head, "bodySha256": digest.hexdigest(), "bodyBytes": count,
                      "completedAt": _now()}
            received = None if verify_transfer and response.status == 200 else b"".join(chunks)
            if received is None:
                if count != self.plan["transfer"]["bytes"] or digest.hexdigest() != self.plan["transfer"]["sha256"]:
                    _write_json(directory / "verification-mismatch.json", record)
                    _fail("STAGED_BYTES_MISMATCH", "The staged resource is not the original complete transfer.",
                          actualSha256=digest.hexdigest(), actualBytes=count)
                record["bodyReference"] = "transfer.zip"
            else:
                if endpoint == "/members/users/authenticated" and response.status == 200:
                    user = _parse(received)
                    if not isinstance(user, dict):
                        _fail("INVALID_ACCOUNT_RESPONSE", "Expected the original authenticated-user object.")
                    record["providerBodySha256"] = record["bodySha256"]
                    record["providerBodyBytes"] = record["bodyBytes"]
                    record["retainedBodyKind"] = "authenticated-user-identity-projection"
                    received = _json({key: user.get(key) for key in ("id", "uuid", "name", "active", "guest", "type")})
                    record["bodySha256"], record["bodyBytes"] = _sha(received), len(received)
                _write(directory / "response.body", received)
            _write_json(directory / "response.json", record)
            if response.status not in expected:
                _fail(_error_class(response.status), "Repository returned an error.",
                      status=response.status, response=str(directory.relative_to(self.root)),
                      retryAfter=headers.get("retry-after"))
            return record, received
        except BaseException as exc:
            try:
                _write_json(directory / ("error-" + str(time.time_ns()) + ".json"),
                            {"at": _now(), "phase": phase, "kind": type(exc).__name__,
                             "code": exc.code if isinstance(exc, RodaError) else "HTTP_TRANSPORT_FAILED",
                             "mutationDispatched": mutation and (directory / "dispatch.json").exists()})
            except OSError:
                pass
            if isinstance(exc, (RodaError, KeyboardInterrupt, SystemExit)):
                raise
            _fail("HTTP_TRANSPORT_FAILED", "Repository transport did not produce a complete saved response.",
                  phase=phase, cause=type(exc).__name__,
                  mutationDispatched=mutation and (directory / "dispatch.json").exists())
        finally:
            connection.close()

    def _api(self, method, endpoint, *, value=None, stage=None, mutation=False, expected=(200,)):
        _, body = self._request(method, endpoint, body=_json(value) if value is not None else None,
                                mutation=mutation, stage=stage, expected=expected)
        value = _parse(body)
        if not isinstance(value, dict):
            _fail("INVALID_API_OBJECT", "The original RODA endpoint must return a JSON object.")
        return value

    def authenticate(self):
        if self.actor is not None:
            return {"username": self.actor}
        user = self._api("GET", "/members/users/authenticated")
        if (not isinstance(user, dict) or user.get("name") != self.config["repositoryUsername"]
                or user.get("guest") is True or user.get("active") is False):
            _fail("AUTHENTICATED_ACTOR_MISMATCH", "The repository authenticated a different or inactive user.")
        self.actor = user["name"]
        return {"username": user["name"], "id": user.get("id"), "uuid": user.get("uuid")}

    def _find(self, resource, filters):
        offset, seen, rows, totals = 0, set(), [], []
        limit = self.config["reportPageSize"]
        for _ in range(self.config["maxPages"]):
            result = self._api("POST", "/" + resource + "/find", value={
                "filter": {"parameters": [{"@type": "SimpleFilterParameter", "name": key, "value": value}
                                           for key, value in filters]},
                "onlyActive": False, "sorter": {"parameters": [{"name": "uuid", "descending": False}]},
                "sublist": {"firstElementIndex": offset, "maximumElementCount": limit}})
            if not isinstance(result, dict) or not isinstance(result.get("results"), list):
                _fail("INVALID_INDEX_RESPONSE", "Expected the original RODA IndexResult.")
            batch = result["results"]
            total = result.get("totalCount")
            if isinstance(total, bool) or not isinstance(total, int) or total < 0:
                _fail("INVALID_INDEX_RESPONSE", "IndexResult must include its nonnegative totalCount.")
            if result.get("offset", offset) != offset:
                _fail("INDEX_OFFSET_MISMATCH", "Repository returned a different search page offset.")
            totals.append(total)
            for row in batch:
                if not isinstance(row, dict):
                    _fail("INVALID_INDEX_RESPONSE", "Index rows must be objects.")
                identity = row.get("uuid") or row.get("id")
                if not identity or identity in seen:
                    _fail("INDEX_PAGE_OVERLAP", "Search pages overlap or omit an object identifier.")
                seen.add(identity)
                rows.append(row)
            offset += len(batch)
            if offset >= total:
                if any(x != total for x in totals):
                    _fail("INDEX_CHANGED_DURING_READ", "Repository index changed while this recovery was paged.")
                return rows
            if not batch:
                _fail("INCOMPLETE_INDEX_RESPONSE", "Index pagination ended before its reported total.")
        _fail("INDEX_PAGE_LIMIT", "Continue reconciliation with an appropriate configured pagination limit.")

    def _validate_transfer(self, resource, *, job_move=False):
        if not isinstance(resource, dict):
            _fail("INVALID_TRANSFER_RESPONSE", "Expected the original transferred resource.")
        _id(resource.get("uuid"), "transfer.uuid")
        if resource.get("name") != self.plan["uploadName"] or resource.get("file") is not True:
            _fail("TRANSFER_IDENTITY_MISMATCH", "Staged resource is not this operation's selected ZIP.")
        if resource.get("size") != self.plan["transfer"]["bytes"]:
            _fail("STAGED_SIZE_MISMATCH", "Staged ZIP length differs from the original transfer.")
        parent = resource.get("parentUUID") or None
        if not job_move and parent != self.config.get("stagingParentUuid"):
            _fail("STAGING_PARENT_MISMATCH", "Staged resource belongs to a different parent.")
        return resource

    def _accept_transfer(self, resource, source):
        resource = self._validate_transfer(resource)
        uuid = resource["uuid"]
        record, _ = self._request("GET", "/transfers/" + urllib.parse.quote(uuid, safe="") + "/download",
                                  verify_transfer=True)
        accepted = {"schema": "stellar-forge.roda-upload-accepted.v1", "operationId": self.plan["operationId"],
                    "uuid": uuid, "name": resource["name"], "relativePath": resource.get("relativePath"),
                    "parentUUID": resource.get("parentUUID"), "bytes": self.plan["transfer"]["bytes"],
                    "sha256": self.plan["transfer"]["sha256"], "source": source,
                    "download": {"bodySha256": record["bodySha256"], "bodyBytes": record["bodyBytes"]}}
        _write_json(self.remote / "upload" / "accepted.json", accepted)
        return accepted

    def _recover_upload(self, transfer_uuid=None):
        accepted = _optional_json(self.remote / "upload" / "accepted.json")
        if accepted:
            if (accepted.get("operationId") != self.plan["operationId"]
                    or accepted.get("sha256") != self.plan["transfer"]["sha256"]
                    or accepted.get("bytes") != self.plan["transfer"]["bytes"]):
                _fail("SAVED_UPLOAD_BINDING_CHANGED", "Saved upload does not match the original operation.")
            if transfer_uuid is not None and transfer_uuid != accepted["uuid"]:
                _fail("TRANSFER_SELECTION_CONFLICT", "This operation already selected another transferred UUID.")
            return accepted
        if transfer_uuid is not None:
            resource = self._api("GET", "/transfers/" + urllib.parse.quote(_id(transfer_uuid, "transferUuid"), safe=""))
            return self._accept_transfer(resource, "operator-selected-original-uuid")
        response = self._completed(self.remote / "upload")
        if response and response[0]["status"] == 201:
            return self._accept_transfer(_parse(response[1]), "original-upload-response")
        if not (self.remote / "upload" / "dispatch.json").exists():
            return None
        filters = [("name", self.plan["uploadName"])]
        if self.config.get("stagingParentUuid"):
            filters.append(("parentUUID", self.config["stagingParentUuid"]))
        found = self._find("transfers", filters)
        found = [r for r in found if r.get("name") == self.plan["uploadName"]
                 and (r.get("parentUUID") or None) == self.config.get("stagingParentUuid")]
        if len(found) > 1:
            _fail("MULTIPLE_UPLOAD_MATCHES", "More than one staged resource matches the original upload identity.")
        if found:
            return self._accept_transfer(found[0], "original-upload-index-reconciliation")
        return None

    def upload(self):
        self._require_plan()
        self.authenticate()
        existing = self._recover_upload()
        if existing:
            return self.local_status()
        if (self.remote / "upload" / "dispatch.json").exists():
            _fail("UPLOAD_UNRESOLVED", "The original upload was dispatched but its complete resource is not yet discoverable.",
                  operationId=self.plan["operationId"], uploadName=self.plan["uploadName"])
        if self.config.get("stagingParentUuid"):
            parent = self._api("GET", "/transfers/" + urllib.parse.quote(self.config["stagingParentUuid"], safe=""))
            if parent.get("uuid") != self.config["stagingParentUuid"] or parent.get("file") is not False:
                _fail("INVALID_STAGING_PARENT", "Configured staging parent must be the selected existing folder.")
        query = {"commit": "true"}
        if self.config.get("stagingParentUuid"):
            query["parent-uuid"] = self.config["stagingParentUuid"]
        _, body = self._request("POST", "/transfers/create/resource?" + urllib.parse.urlencode(query),
                                 multipart=True, mutation=True, stage="upload", expected=(201,))
        self._accept_transfer(_parse(body), "original-upload-response")
        return self.local_status()

    def _job_request(self, accepted):
        value = dict(self.plan["jobTemplate"])
        value["pluginParameters"] = dict(value["pluginParameters"])
        value["name"] = self.plan["jobName"]
        value["sourceObjects"] = {"@type": "SelectedItemsListRequest", "ids": [accepted["uuid"]]}
        value["sourceObjectsClass"] = TRANSFER_CLASS
        return value

    def _job_model(self, job_id):
        job_id = _id(job_id, "job.id")
        job = self._api("GET", "/jobs/" + urllib.parse.quote(job_id, safe=""))
        if job.get("id") != job_id:
            _fail("JOB_IDENTITY_MISMATCH", "Repository returned a different full job model.")
        return job

    def _job_parameters(self, job, request):
        requested, effective = request["pluginParameters"], job.get("pluginParameters")
        if not isinstance(effective, dict) or not all(
                isinstance(k, str) and isinstance(v, str) for k, v in effective.items()):
            _fail("INVALID_JOB_PARAMETERS", "The full job must retain its string-to-string parameter map.")
        for key, value in requested.items():
            if effective.get(key) != value:
                _fail("JOB_PARAMETER_MISMATCH", "A requested ingest parameter changed.", field=key)
        unexpected = set(effective) - set(requested) - DERIVED_JOB_PARAMETERS
        if unexpected:
            _fail("UNREVIEWED_JOB_PARAMETERS", "The job contains additional parameters outside the reviewed server contract.",
                  fields=sorted(unexpected))
        maximum = 5 if request["plugin"].endswith(".MinimalIngestPlugin") else 11
        steps = effective.get("parameter.total_steps")
        if (not isinstance(steps, str) or not re.fullmatch(r"[1-9][0-9]*", steps)
                or not 1 <= int(steps) <= maximum):
            _fail("INVALID_DERIVED_JOB_PARAMETER", "The original effective ingest-step count is invalid.",
                  field="parameter.total_steps")
        if effective.get("parameter.create_submission") not in {"true", "false"}:
            _fail("INVALID_DERIVED_JOB_PARAMETER", "The repository submission setting must be a lowercase boolean.",
                  field="parameter.create_submission")
        if effective.get("parameter.reporting_class") != request["plugin"]:
            _fail("INVALID_DERIVED_JOB_PARAMETER", "The report class must be the selected concrete ingest plugin.",
                  field="parameter.reporting_class")
        return {"requestedSha256": _sha(_json(requested)), "effectiveSha256": _sha(_json(effective)),
                "derivedParameters": {key: effective[key] for key in sorted(set(effective) - set(requested))},
                "sourceCommit": SOURCE_COMMIT}

    def _source_identity(self, job, request, current_uuid):
        upload = _optional_json(self.remote / "upload" / "accepted.json")
        if (not upload or upload.get("operationId") != self.plan["operationId"]
                or upload.get("uuid") != request["sourceObjects"]["ids"][0]
                or upload.get("sha256") != self.plan["transfer"]["sha256"]
                or upload.get("bytes") != self.plan["transfer"]["bytes"]):
            _fail("SAVED_UPLOAD_BINDING_CHANGED", "Job source requires the original verified upload.")
        return {"schema": "stellar-forge.roda-job-source-binding.v1",
                "operationId": self.plan["operationId"], "jobId": job["id"],
                "requestSha256": _sha(_json(request)), "originalUuid": request["sourceObjects"]["ids"][0],
                "originalRelativePath": upload.get("relativePath"),
                "currentUuid": _id(current_uuid, "job.sourceUuid"),
                "name": self.plan["uploadName"], "bytes": self.plan["transfer"]["bytes"],
                "sha256": self.plan["transfer"]["sha256"]}

    def _read_source_binding(self, path, job, request):
        value = _read_json(path)
        if not isinstance(value, dict):
            _fail("JOB_SOURCE_BINDING_CHANGED", "Saved source movement must be an object.")
        identity = self._source_identity(job, request, value.get("currentUuid"))
        if any(value.get(key) != expected for key, expected in identity.items()):
            _fail("JOB_SOURCE_BINDING_CHANGED", "Saved movement is not bound to this job and original transfer.")
        canonical = {key: item for key, item in value.items() if key != "bindingSha256"}
        if value.get("bindingSha256") != _sha(_json(canonical)):
            _fail("JOB_SOURCE_BINDING_CHANGED", "The original saved movement bytes have changed.")
        if path.name != _sha(_json(identity)) + ".json" or value.get("kind") != "SAME_JOB_MOVED_SOURCE":
            _fail("JOB_SOURCE_BINDING_CHANGED", "Saved movement identity differs from its immutable file.")
        resource, download = value.get("resource"), value.get("download")
        self._validate_transfer(resource, job_move=True)
        if (resource.get("uuid") != identity["currentUuid"] or not isinstance(download, dict)
                or download.get("bodySha256") != identity["sha256"]
                or download.get("bodyBytes") != identity["bytes"] or download.get("status") != 200):
            _fail("JOB_SOURCE_BINDING_CHANGED", "Saved moved-source verification differs from the original transfer.")
        return value

    def _job_source(self, job, request):
        source = job.get("sourceObjects")
        if (not isinstance(source, dict) or source.get("type") != "list"
                or not isinstance(source.get("ids"), list) or len(source["ids"]) != 1
                or source.get("selectedClass") != TRANSFER_CLASS):
            _fail("JOB_SOURCE_MISMATCH", "The full job must select one transferred-resource source.")
        current_uuid = _id(source["ids"][0], "job.sourceUuid")
        identity = self._source_identity(job, request, current_uuid)
        if current_uuid == identity["originalUuid"]:
            return {**identity, "kind": "ORIGINAL_UPLOAD"}
        path = self.remote / "job" / "source-moves" / (_sha(_json(identity)) + ".json")
        if path.exists():
            return self._read_source_binding(path, job, request)
        # The original autoaccept workflow can move a SIP and rewrite the job
        # and report source UUID. Bind that observation to this same job plus
        # its actual unchanged ZIP; never replace the original upload record.
        try:
            resource = self._validate_transfer(
                self._api("GET", "/transfers/" + urllib.parse.quote(current_uuid, safe="")), job_move=True)
            if resource["uuid"] != current_uuid:
                _fail("JOB_SOURCE_MISMATCH", "Repository returned a different moved source.")
            download, _ = self._request(
                "GET", "/transfers/" + urllib.parse.quote(current_uuid, safe="") + "/download",
                verify_transfer=True)
        except RodaError as exc:
            if exc.code != "REMOTE_NOT_FOUND":
                raise
            _fail("JOB_SOURCE_MOVE_UNRESOLVED", "The job's current source is not yet retrievable; reopen this same job.",
                  jobId=job["id"], originalTransferUuid=identity["originalUuid"],
                  currentTransferUuid=current_uuid, response=exc.details.get("response"))
        value = {**identity, "kind": "SAME_JOB_MOVED_SOURCE", "observedAt": _now(),
                 "jobSourceObjects": source, "resource": resource, "download": download,
                 "basis": "same-job-selected-source-and-original-complete-zip",
                 "sourceCommit": SOURCE_COMMIT}
        value["bindingSha256"] = _sha(_json(value))
        _write_json(path, value)
        return self._read_source_binding(path, job, request)

    def _known_job_sources(self, job, request):
        current = self._job_source(job, request)
        known = {current["originalUuid"], current["currentUuid"]}
        directory = self.remote / "job" / "source-moves"
        if directory.exists():
            paths = sorted(directory.iterdir())
            if len(paths) > 10000:
                _fail("JOB_SOURCE_HISTORY_LIMIT", "Source movement history exceeds the receiving limit.")
            for path in paths:
                # Ignore the original writer's unpublished .write-* files.
                if path.name.startswith(".write-"):
                    continue
                if path.suffix != ".json":
                    _fail("JOB_SOURCE_BINDING_CHANGED", "Unexpected file in source movement history.")
                known.add(self._read_source_binding(path, job, request)["currentUuid"])
        return current, known

    def _validate_job(self, job, request):
        if not isinstance(job, dict):
            _fail("INVALID_JOB_RESPONSE", "Expected the full original RODA job model.")
        _id(job.get("id"), "job.id")
        for key in ("name", "plugin", "priority", "parallelism"):
            if job.get(key) != request[key]:
                _fail("JOB_IDENTITY_MISMATCH", "Job model differs from the original submitted request.", field=key)
        if job.get("username") != self.config["repositoryUsername"]:
            _fail("JOB_ACTOR_MISMATCH", "Job belongs to a different repository user.")
        self._job_parameters(job, request)
        self._job_source(job, request)
        if job.get("state") not in KNOWN_STATES:
            _fail("UNKNOWN_JOB_STATE", "The repository returned an unknown job state.", state=job.get("state"))
        return job

    def _accept_job(self, job, request, source):
        job = self._validate_job(job, request)
        value = {"schema": "stellar-forge.roda-job-accepted.v1", "operationId": self.plan["operationId"],
                 "jobId": job["id"], "requestSha256": _sha(_json(request)),
                 "transferUuid": request["sourceObjects"]["ids"][0], "source": source,
                 "parameters": self._job_parameters(job, request),
                 "acceptedSource": self._job_source(job, request)}
        _write_json(self.remote / "job" / "accepted.json", value)
        return value

    def _recover_job(self, accepted_upload, job_id=None):
        request = self._job_request(accepted_upload)
        accepted = _optional_json(self.remote / "job" / "accepted.json")
        if accepted:
            if (accepted.get("operationId") != self.plan["operationId"]
                    or accepted.get("requestSha256") != _sha(_json(request))
                    or accepted.get("transferUuid") != accepted_upload["uuid"]):
                _fail("SAVED_JOB_BINDING_CHANGED", "Saved job does not match its original request.")
            if job_id is not None and job_id != accepted["jobId"]:
                _fail("JOB_SELECTION_CONFLICT", "This operation has already selected another job.")
            return accepted
        if job_id is not None:
            job = self._job_model(job_id)
            return self._accept_job(job, request, "operator-selected-original-job")
        response = self._completed(self.remote / "job")
        if response and response[0]["status"] == 201:
            job = _parse(response[1])
            # Reopen the full model even when an ingress proxy returned a projection.
            job = self._job_model(job.get("id"))
            return self._accept_job(job, request, "original-create-response")
        candidates = self._find("jobs", [("name", self.plan["jobName"]),
                                         ("username", self.config["repositoryUsername"])])
        candidates = [r for r in candidates if r.get("name") == self.plan["jobName"]
                      and r.get("username") == self.config["repositoryUsername"]]
        if len(candidates) > 1:
            _fail("MULTIPLE_JOB_MATCHES", "More than one job carries the immutable original operation marker.",
                  jobIds=[r.get("id") for r in candidates])
        if candidates:
            job = self._job_model(candidates[0].get("id"))
            return self._accept_job(job, request, "original-create-index-reconciliation")
        return None

    def submit(self):
        self._require_plan()
        self.authenticate()
        upload = self._recover_upload()
        if upload is None:
            _fail("VERIFIED_UPLOAD_REQUIRED", "The original complete staged bytes must be verified before ingest.")
        existing = self._recover_job(upload)
        if existing:
            return self.local_status()
        if (self.remote / "job" / "dispatch.json").exists():
            _fail("JOB_CREATION_UNRESOLVED", "The original create request is retained; reconcile its job before another submission.",
                  operationId=self.plan["operationId"], jobName=self.plan["jobName"])
        # Verify current staging bytes just before the one job submission.
        resource = self._api("GET", "/transfers/" + urllib.parse.quote(upload["uuid"], safe=""))
        self._validate_transfer(resource)
        self._request("GET", "/transfers/" + urllib.parse.quote(upload["uuid"], safe="") + "/download",
                      verify_transfer=True)
        request = self._job_request(upload)
        _write_json(self.remote / "job" / "create-request.json", request)
        job = self._api("POST", "/jobs", value=request, mutation=True, stage="job", expected=(201,))
        model = self._job_model(job.get("id"))
        self._accept_job(model, request, "original-create-response")
        return self.local_status()

    def _reports(self, job_id):
        reports, seen, start = [], set(), 0
        limit = self.config["reportPageSize"]
        for _ in range(self.config["maxPages"]):
            result = self._api("GET", "/jobs/" + urllib.parse.quote(job_id, safe="") + "/reports?" +
                               urllib.parse.urlencode({"job-just-failed": "false", "start": start, "limit": limit}))
            batch = result.get("reports") if isinstance(result, dict) else None
            if not isinstance(batch, list):
                _fail("INVALID_REPORTS_RESPONSE", "Expected the original RODA Reports object.")
            for indexed in batch:
                if not isinstance(indexed, dict):
                    _fail("INVALID_REPORTS_RESPONSE", "Each indexed report must be an original object.")
                report_id = _id(indexed.get("id"), "report.id")
                if report_id in seen:
                    _fail("REPORT_PAGE_OVERLAP", "Report pagination returned a repeated original report.")
                seen.add(report_id)
                model = self._api("GET", "/jobs/" + urllib.parse.quote(job_id, safe="") +
                                  "/report/" + urllib.parse.quote(report_id, safe=""))
                if model.get("id") != report_id or model.get("jobId") != job_id:
                    _fail("REPORT_JOB_MISMATCH", "Report model does not belong to the selected original job.")
                reports.append(model)
            start += len(batch)
            if len(batch) < limit:
                return reports
        _fail("REPORT_PAGE_LIMIT", "Report enumeration reached the selected page limit before completion.")

    def _outcome(self, job, reports, upload):
        stats = job.get("jobStats")
        if not isinstance(stats, dict):
            _fail("JOB_STATS_MISSING", "The full job model must retain its per-object counters.")
        source_binding, source_ids = self._known_job_sources(job, self._job_request(upload))
        report_rows, aip_ids, failures = [], set(), []
        def visit(report, depth=0):
            if depth > 32 or len(report_rows) >= 100000:
                _fail("REPORT_NESTING_LIMIT", "Report structure exceeds the supported receiving bound.")
            if not isinstance(report, dict):
                _fail("INVALID_REPORT", "Nested report must be an object.")
            if report.get("jobId") not in {None, job["id"]}:
                _fail("REPORT_JOB_MISMATCH", "Nested report belongs to another job.")
            source_id = report.get("sourceObjectId")
            row = {k: report.get(k) for k in ("id", "jobId", "sourceObjectId", "sourceObjectClass",
                                              "outcomeObjectId", "outcomeObjectClass", "outcomeObjectState",
                                              "plugin", "pluginState", "pluginIsMandatory", "pluginDetails")}
            report_rows.append(row)
            if row["pluginState"] in {"FAILURE", "PARTIAL_SUCCESS"}:
                failures.append(row)
            if (source_id in source_ids and row["sourceObjectClass"] == TRANSFER_CLASS
                    and row["outcomeObjectId"] not in {None, "", "NO_OUTCOME_ID"}
                    and row["outcomeObjectClass"] in {AIP_CLASS, "org.roda.core.data.v2.ip.IndexedAIP"}):
                aip_ids.add(_id(row["outcomeObjectId"], "outcomeObjectId"))
            children = report.get("reports", [])
            if children is not None:
                if not isinstance(children, list):
                    _fail("INVALID_REPORT", "Nested reports must be a list.")
                for child in children:
                    visit(child, depth + 1)
        for report in reports:
            visit(report)
        aips, unresolved_aips = [], []
        for aip_id in sorted(aip_ids):
            try:
                aip = self._api("GET", "/aips/" + urllib.parse.quote(aip_id, safe=""))
            except RodaError as exc:
                if exc.code != "REMOTE_NOT_FOUND":
                    raise
                unresolved_aips.append({"id": aip_id, "state": "NOT_YET_RETRIEVABLE",
                                        "response": exc.details.get("response")})
                continue
            if aip.get("id") != aip_id:
                _fail("AIP_IDENTITY_MISMATCH", "Repository returned a different result AIP.")
            parent = self.inputs["handoff"].get("collection", {}).get("parentAipId")
            if (aip.get("parentId") or "") != (parent or ""):
                _fail("AIP_COLLECTION_MISMATCH", "Result AIP is outside the reviewed parent collection.")
            aips.append(aip)
        state = job["state"]
        status = "INGEST_RUNNING"
        if state in PAUSED:
            status = "JOB_" + state
        elif state in TERMINAL - {"COMPLETED"}:
            status = "JOB_" + state
        elif state == "COMPLETED":
            counts = {key: stats.get(key) for key in (
                "sourceObjectsCount", "sourceObjectsBeingProcessed", "sourceObjectsWaitingToBeProcessed",
                "sourceObjectsProcessedWithSuccess", "sourceObjectsProcessedWithPartialSuccess", "sourceObjectsProcessedWithFailure",
                "sourceObjectsProcessedWithSkipped", "outcomeObjectsWithManualIntervention")}
            if any(isinstance(v, bool) or not isinstance(v, int) or v < 0 for v in counts.values()):
                _fail("JOB_STATS_INCOMPLETE", "Completed job counters are incomplete or invalid.")
            if (counts["sourceObjectsCount"] != 1 or not reports or len(aips) != 1 or unresolved_aips
                    or counts["sourceObjectsBeingProcessed"] or counts["sourceObjectsWaitingToBeProcessed"]):
                status = "INGEST_RESULT_INCOMPLETE"
            elif (failures or counts["sourceObjectsProcessedWithFailure"]
                  or counts["sourceObjectsProcessedWithPartialSuccess"]
                  or counts["sourceObjectsProcessedWithSkipped"]):
                status = "INGEST_REVIEW_REQUIRED"
            elif (counts["outcomeObjectsWithManualIntervention"]
                  or aips[0].get("state") == "UNDER_APPRAISAL"):
                status = "AIP_UNDER_APPRAISAL"
            elif counts["sourceObjectsProcessedWithSuccess"] == 1 and aips[0].get("state") == "ACTIVE":
                status = "INGESTED_ACTIVE"
            else:
                status = "AIP_" + str(aips[0].get("state", "UNKNOWN"))
        return {"schema": "stellar-forge.roda-ingest-observation.v1",
                "operationId": self.plan["operationId"], "observedAt": _now(), "status": status,
                "jobId": job["id"], "jobState": state, "jobStats": stats, "job": job,
                "uploadUuid": upload["uuid"], "currentTransferUuid": source_binding["currentUuid"],
                "sourceBinding": source_binding, "verifiedSourceUuids": sorted(source_ids),
                "jobParameters": self._job_parameters(job, self._job_request(upload)),
                "reports": reports, "reportRows": report_rows,
                "aips": aips, "unresolvedAips": unresolved_aips, "resultAipIds": sorted(aip_ids),
                "reportPaginationComplete": True, "packageModel": "one-bag-one-aip"}

    def reconcile(self, *, transfer_uuid=None, job_id=None, poll_seconds=0, interval_seconds=5):
        self._require_plan()
        self.authenticate()
        if not isinstance(poll_seconds, (int, float)) or not 0 <= poll_seconds <= 86400:
            _fail("INVALID_POLL_TIMEOUT", "poll_seconds must be between zero and 86400.")
        if not isinstance(interval_seconds, (int, float)) or not 1 <= interval_seconds <= 3600:
            _fail("INVALID_POLL_INTERVAL", "interval_seconds must be between one and 3600.")
        upload = self._recover_upload(transfer_uuid)
        if upload is None:
            result = {**self.local_status(), "status": "UPLOAD_UNRESOLVED" if (self.remote / "upload" / "dispatch.json").exists() else "PREPARED"}
            return result
        accepted = self._recover_job(upload, job_id)
        if accepted is None:
            return {**self.local_status(), "status": "JOB_CREATION_UNRESOLVED" if (self.remote / "job" / "dispatch.json").exists() else "UPLOADED_VERIFIED"}
        request = self._job_request(upload)
        deadline = time.monotonic() + poll_seconds
        while True:
            job = self._validate_job(self._job_model(accepted["jobId"]), request)
            if job["state"] in TERMINAL | PAUSED or time.monotonic() >= deadline:
                break
            time.sleep(min(interval_seconds, max(0, deadline - time.monotonic())))
        reports = self._reports(job["id"])
        latest = self._validate_job(self._job_model(job["id"]), request)
        observation = self._outcome(latest, reports, upload)
        if (latest["state"] != job["state"] or latest.get("jobStats") != job.get("jobStats")
                or latest.get("endDate") != job.get("endDate")
                or latest.get("sourceObjects") != job.get("sourceObjects")):
            observation["status"] = "JOB_CHANGED_DURING_RECONCILIATION"
            observation["reportPaginationComplete"] = False
        path = self.remote / "observations" / (_sha(_json(observation)) + ".json")
        _write_json(path, observation)
        _write_json(self.remote / "latest.json", {"path": str(path.relative_to(self.remote)),
                    "sha256": _sha(_json(observation)), "operationId": self.plan["operationId"]}, replace=True)
        return self.local_status()

    def local_status(self):
        if self.plan is None:
            return {"schema": SCHEMA, "status": "HANDOFF_VERIFIED", "handoffSha256": self.inputs["handoffSha256"]}
        upload = _optional_json(self.remote / "upload" / "accepted.json")
        job = _optional_json(self.remote / "job" / "accepted.json")
        if upload:
            if (upload.get("operationId") != self.plan["operationId"]
                    or upload.get("sha256") != self.plan["transfer"]["sha256"]
                    or upload.get("bytes") != self.plan["transfer"]["bytes"]
                    or upload.get("name") != self.plan["uploadName"]
                    or (upload.get("parentUUID") or None) != self.plan["config"].get("stagingParentUuid")):
                _fail("SAVED_UPLOAD_BINDING_CHANGED", "Saved upload does not match the original plan.")
            _id(upload.get("uuid"), "transfer.uuid")
        if job:
            if (not upload or job.get("operationId") != self.plan["operationId"]
                    or job.get("requestSha256") != _sha(_json(self._job_request(upload)))
                    or job.get("transferUuid") != upload["uuid"]):
                _fail("SAVED_JOB_BINDING_CHANGED", "Saved job does not match the original upload and request.")
            _id(job.get("jobId"), "job.id")
        state = ("JOB_ACCEPTED" if job else "JOB_CREATION_UNRESOLVED" if (self.remote / "job" / "dispatch.json").exists()
                 else "UPLOADED_VERIFIED" if upload else "UPLOAD_UNRESOLVED" if (self.remote / "upload" / "dispatch.json").exists()
                 else "PREPARED")
        result = {"schema": SCHEMA, "status": state, "operationId": self.plan["operationId"],
                  "repository": self.plan["config"]["baseUrl"],
                  "repositoryUsername": self.plan["config"]["repositoryUsername"],
                  "handoffSha256": self.plan["handoffSha256"], "uploadName": self.plan["uploadName"],
                  "jobName": self.plan["jobName"], "transferUuid": upload.get("uuid") if upload else None,
                  "jobId": job.get("jobId") if job else None}
        pointer = _optional_json(self.remote / "latest.json")
        if pointer:
            raw = _read(_relative(self.remote, pointer["path"]), JSON_LIMIT * 4)
            if _sha(raw) != pointer.get("sha256"):
                _fail("OBSERVATION_HASH_MISMATCH", "The saved latest observation has changed.")
            value = _parse(raw)
            if value.get("operationId") != self.plan["operationId"]:
                _fail("OBSERVATION_OPERATION_MISMATCH", "Saved observation belongs to a different original operation.")
            result.update({k: value.get(k) for k in ("status", "jobState", "jobStats", "resultAipIds", "currentTransferUuid",
                                                   "reportPaginationComplete", "observedAt")})
            result["observation"] = "remote/" + pointer["path"]
        return result


def _operate(workspace, config_file, callback):
    root = Path(workspace).resolve(strict=True)
    with _root_lock(root):
        return callback(_Client(root, config_file))


def plan(workspace, config_file, job_template_file):
    return _operate(workspace, config_file, lambda c: c.prepare(job_template_file))


def upload(workspace, config_file):
    return _operate(workspace, config_file, lambda c: c.upload())


def submit(workspace, config_file):
    return _operate(workspace, config_file, lambda c: c.submit())


def reconcile(workspace, config_file, *, transfer_uuid=None, job_id=None, poll_seconds=0, interval_seconds=5):
    return _operate(workspace, config_file, lambda c: c.reconcile(
        transfer_uuid=transfer_uuid, job_id=job_id, poll_seconds=poll_seconds, interval_seconds=interval_seconds))


def status(workspace):
    return _operate(workspace, None, lambda c: c.local_status())


def run(workspace, config_file, job_template_file=None, poll_seconds=0):
    def work(client):
        client.prepare(job_template_file)
        client.upload()
        client.submit()
        return client.reconcile(poll_seconds=poll_seconds)
    return _operate(workspace, config_file, work)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("command", choices=["plan", "upload", "submit", "reconcile", "run", "status"])
    parser.add_argument("--workspace", required=True)
    parser.add_argument("--config")
    parser.add_argument("--job-template")
    parser.add_argument("--transfer-uuid")
    parser.add_argument("--job-id")
    parser.add_argument("--poll-seconds", type=float, default=0)
    parser.add_argument("--interval-seconds", type=float, default=5)
    args = parser.parse_args(argv)
    if args.command != "status" and not args.config:
        parser.error("--config is required for repository operations")
    if args.command == "plan" and not args.job_template:
        parser.error("--job-template is required for plan")
    if args.command != "reconcile" and (args.transfer_uuid or args.job_id):
        parser.error("--transfer-uuid and --job-id select existing records only during reconcile")
    try:
        if args.command == "plan":
            result = plan(args.workspace, args.config, args.job_template)
        elif args.command == "upload":
            result = upload(args.workspace, args.config)
        elif args.command == "submit":
            result = submit(args.workspace, args.config)
        elif args.command == "run":
            result = run(args.workspace, args.config, args.job_template, args.poll_seconds)
        elif args.command == "reconcile":
            result = reconcile(args.workspace, args.config, transfer_uuid=args.transfer_uuid,
                               job_id=args.job_id, poll_seconds=args.poll_seconds,
                               interval_seconds=args.interval_seconds)
        else:
            result = status(args.workspace)
        print(json.dumps(result, ensure_ascii=False, sort_keys=True, indent=2))
        return 0
    except RodaError as exc:
        print(json.dumps(exc.result(), ensure_ascii=False, sort_keys=True, indent=2), file=sys.stderr)
        return 2
    except KeyboardInterrupt:
        print(json.dumps({"schema": SCHEMA, "error": "INTERRUPTED",
                          "message": "Reopen the same workspace to reconcile the retained request."}), file=sys.stderr)
        return 130
    except OSError as exc:
        print(json.dumps({"schema": SCHEMA, "error": "LOCAL_IO_ERROR",
                          "cause": type(exc).__name__, "errno": exc.errno,
                          "message": "The original journal remains the continuation source."}), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

